-- ── Mata Hari ──
INSERT INTO `brands` (`name`, `country_id`, `founded`, `factory`, `source`, `mentions`, `history`, `gamme`, `history_en`, `gamme_en`, `history_es`, `gamme_es`, `history_de`, `gamme_de`, `history_zh`, `gamme_zh`, `history_ar`, `gamme_ar`)
VALUES ('Mata Hari',
        'indonesia',
        '2024 — Sonny Suciawan et Sebastian (Allemagne)',
        'Indonésie — la maison ne nomme pas sa fabrique',
        'tobaccoasia.com « The Renaissance of Indonesia''s Premium Cigar Industry » (consulté 2026-09-24 : Sonny Suciawan cofondateur de Monsoon Cigar Company, sélection de la feuille avec PT Besuki Raya Cigars à Jember, Java Est, portefeuille Mata Hari) ; tobaccoasia.com « Tobacco Asia Podcast #41: Sonny Suciawan, Mata Hari » (2025-02-18 : entretien avec Sonny Suciawan sur la marque Mata Hari, ses origines et son ambition commerciale) ; monsooncigar.com « Cigars made by Monsoon Cigar Company » (consulté 2026-09-24 : description des trois vitolas Mata Hari, capes et compositions) ; monsooncigar.com « About us » (consulté 2026-09-24 : fondation de Monsoon Cigar Company par Sonny Suciawan et Sebastian, rencontre en Allemagne) ; monsooncigar.com « Cigar Events with Monsoon Cigar Company » (consulté 2026-09-24 : tournée de dégustations à Jakarta et Bandung en novembre 2024, aucun événement postérieur listé) ; cigarworld.de « Mata Hari » (consulté 2026-09-24 : trois vitolas encore au catalogue de ce détaillant allemand)',
        NULL,
        'Monsoon Cigar Company naît, dit la maison, de la rencontre de Sonny Suciawan et de Sebastian sur une ferme du Brandebourg, en Allemagne ; elle lance sa première marque, Mata Hari, en 2024, d''abord en Allemagne. Le nom est celui de la danseuse néerlandaise exécutée en 1917 pour espionnage ; Suciawan dit vouloir faire connaître le cigare indonésien sur les marchés internationaux, Allemagne et États-Unis compris.

Monsoon n''a pas de fabrique propre et ne nomme pas celle qui roule ses cigares. Ses mélanges sont mis au point à Jember, dans l''est de Java, avec PT Besuki Raya Cigar — la maison d''El Gaucho, filiale du groupe Mangli Djaya Raya depuis 2020 —, où Suciawan dit avoir mené des séances de dégustation et de sélection de la feuille. Le catalogue compte trois vitolas : Courtisane, entièrement de tabac indonésien selon la maison ; Java Exotica, tabacs dominicain et brésilien sous une cape de Java dont la première récolte remonte à 2020 ; et la Limited Edition 2024, tabacs brésilien, dominicain et indonésien sous une cape San Andrés mexicaine.

La marque se présente à Berlin en juin 2024, puis à Jakarta et Bandung en novembre 2024 ; Suciawan en parle encore dans un entretien de février 2025. En septembre 2026, Cigarworld.de tient toujours les trois vitolas au catalogue.',
        '[{"name":"Courtisane","color":"#C9A96E","force":"Mild-Medium","wrapper":"Non divulguée","vitolas":[],"story":"Entièrement de tabac indonésien selon la maison, qui lui prête des notes de bois, de cuir, de vanille et de café."},{"name":"Java Exotica","color":"#A0522D","force":"Medium","wrapper":"Java (colorado)","vitolas":[],"story":"Tabacs dominicain et brésilien sous une cape javanaise dont la première récolte remonte à 2020, dit la maison."},{"name":"Limited Edition 2024","color":"#4A3728","force":null,"wrapper":"San Andrés (Mexique)","vitolas":[],"story":"Tabacs brésilien, dominicain et indonésien sous cape San Andrés mexicaine ; notes de terre et de chocolat selon la maison."}]',
        'Monsoon Cigar Company was born, says the house, from the meeting of Sonny Suciawan and Sebastian on a farm in Brandenburg, Germany; it launched its first brand, Mata Hari, in 2024, first in Germany. The name is that of the Dutch dancer executed in 1917 for espionage; Suciawan says he wants to make Indonesian cigars known on international markets, Germany and the United States included.

Monsoon has no factory of its own and does not name the one that rolls its cigars. Its blends are developed in Jember, in eastern Java, with PT Besuki Raya Cigar — the house behind El Gaucho, a subsidiary of the Mangli Djaya Raya group since 2020 — where Suciawan says he ran tasting and leaf-selection sessions. The catalogue has three vitolas: Courtisane, entirely Indonesian tobacco according to the house; Java Exotica, Dominican and Brazilian tobacco under a Java wrapper whose first harvest dates back to 2020; and the Limited Edition 2024, Brazilian, Dominican and Indonesian tobacco under a Mexican San Andrés wrapper.

The brand was presented in Berlin in June 2024, then in Jakarta and Bandung in November 2024; Suciawan still spoke of it in an interview in February 2025. In September 2026, Cigarworld.de still carried all three vitolas in its catalogue.',
        '[{"name":"Courtisane","color":"#C9A96E","force":"Mild-Medium","wrapper":"Undisclosed","vitolas":[],"story":"Entirely Indonesian tobacco according to the house, which gives it notes of wood, leather, vanilla and coffee."},{"name":"Java Exotica","color":"#A0522D","force":"Medium","wrapper":"Java (Colorado)","vitolas":[],"story":"Dominican and Brazilian tobacco under a Java wrapper whose first harvest dates back to 2020, says the house."},{"name":"Limited Edition 2024","color":"#4A3728","force":null,"wrapper":"San Andrés (Mexico)","vitolas":[],"story":"Brazilian, Dominican and Indonesian tobacco under a Mexican San Andrés wrapper; notes of earth and chocolate according to the house."}]',
        'Monsoon Cigar Company nace, dice la casa, del encuentro entre Sonny Suciawan y Sebastian en una granja de Brandeburgo, Alemania; lanza su primera marca, Mata Hari, en 2024, primero en Alemania. El nombre es el de la bailarina neerlandesa ejecutada en 1917 por espionaje; Suciawan dice querer dar a conocer el puro indonesio en los mercados internacionales, Alemania y Estados Unidos incluidos.

Monsoon no tiene fábrica propia y no nombra la que lía sus puros. Sus ligas se ponen a punto en Jember, en el este de Java, con PT Besuki Raya Cigar —la casa de El Gaucho, filial del grupo Mangli Djaya Raya desde 2020—, donde Suciawan dice haber dirigido sesiones de cata y selección de la hoja. El catálogo cuenta con tres vitolas: Courtisane, enteramente de tabaco indonesio según la casa; Java Exotica, tabacos dominicano y brasileño bajo una capa de Java cuya primera cosecha se remonta a 2020; y la Limited Edition 2024, tabacos brasileño, dominicano e indonesio bajo una capa San Andrés mexicana.

La marca se presenta en Berlín en junio de 2024, luego en Yakarta y Bandung en noviembre de 2024; Suciawan sigue hablando de ella en una entrevista de febrero de 2025. En septiembre de 2026, Cigarworld.de sigue teniendo las tres vitolas en su catálogo.',
        '[{"name":"Courtisane","color":"#C9A96E","force":"Mild-Medium","wrapper":"No divulgada","vitolas":[],"story":"Enteramente de tabaco indonesio según la casa, que le atribuye notas de madera, cuero, vainilla y café."},{"name":"Java Exotica","color":"#A0522D","force":"Medium","wrapper":"Java (colorado)","vitolas":[],"story":"Tabacos dominicano y brasileño bajo una capa javanesa cuya primera cosecha se remonta a 2020, dice la casa."},{"name":"Limited Edition 2024","color":"#4A3728","force":null,"wrapper":"San Andrés (México)","vitolas":[],"story":"Tabacos brasileño, dominicano e indonesio bajo capa San Andrés mexicana; notas de tierra y chocolate según la casa."}]',
        'Die Monsoon Cigar Company entsteht, so das Haus, aus der Begegnung von Sonny Suciawan und Sebastian auf einem Hof in Brandenburg, Deutschland; sie bringt 2024 ihre erste Marke, Mata Hari, zunächst in Deutschland auf den Markt. Der Name ist der der niederländischen Tänzerin, die 1917 wegen Spionage hingerichtet wurde; Suciawan sagt, er wolle die indonesische Zigarre auf internationalen Märkten bekannt machen, Deutschland und die Vereinigten Staaten eingeschlossen.

Monsoon besitzt keine eigene Fabrik und nennt nicht diejenige, die ihre Zigarren rollt. Ihre Mischungen werden in Jember, im Osten Javas, entwickelt, bei PT Besuki Raya Cigar — dem Haus hinter El Gaucho, einer Tochtergesellschaft der Mangli-Djaya-Raya-Gruppe seit 2020 —, wo Suciawan nach eigenen Angaben Verkostungs- und Blattauswahlsitzungen geleitet hat. Der Katalog umfasst drei Formate: Courtisane, laut dem Haus vollständig aus indonesischem Tabak; Java Exotica, dominikanischer und brasilianischer Tabak unter einem Java-Deckblatt, dessen erste Ernte auf 2020 zurückgeht; und die Limited Edition 2024, brasilianischer, dominikanischer und indonesischer Tabak unter einem mexikanischen San-Andrés-Deckblatt.

Die Marke wird im Juni 2024 in Berlin vorgestellt, dann im November 2024 in Jakarta und Bandung; Suciawan spricht im Februar 2025 in einem Interview noch davon. Im September 2026 führt Cigarworld.de weiterhin alle drei Formate im Katalog.',
        '[{"name":"Courtisane","color":"#C9A96E","force":"Mild-Medium","wrapper":"Nicht angegeben","vitolas":[],"story":"Laut dem Haus vollständig aus indonesischem Tabak, dem es Noten von Holz, Leder, Vanille und Kaffee zuschreibt."},{"name":"Java Exotica","color":"#A0522D","force":"Medium","wrapper":"Java (Colorado)","vitolas":[],"story":"Dominikanischer und brasilianischer Tabak unter einem javanischen Deckblatt, dessen erste Ernte auf 2020 zurückgeht, so das Haus."},{"name":"Limited Edition 2024","color":"#4A3728","force":null,"wrapper":"San Andrés (Mexiko)","vitolas":[],"story":"Brasilianischer, dominikanischer und indonesischer Tabak unter einem mexikanischen San-Andrés-Deckblatt; Noten von Erde und Schokolade laut dem Haus."}]',
        '据该品牌介绍，Monsoon Cigar Company诞生于桑尼·苏西亚万与塞巴斯蒂安在德国勃兰登堡一处农场的相遇；公司于2024年推出首个品牌Mata Hari，最初在德国上市。这个名字取自1917年因间谍罪被处决的荷兰舞者；苏西亚万说，他希望让印尼雪茄在国际市场——包括德国与美国市场——上更为人知。

Monsoon没有自己的工厂，也不透露是哪家工厂在为其卷制雪茄。其配方在爪哇东部的任抹，由PT Besuki Raya Cigar调制完成——El Gaucho正是产自该厂，该厂自2020年起隶属于Mangli Djaya Raya集团——苏西亚万说，他曾在那里主持品鉴与选叶工作。目录中共有三款规格：Courtisane，据品牌介绍完全采用印尼烟草；Java Exotica，采用多米尼加与巴西烟叶，茄衣为爪哇烟叶，首次采摘可追溯至2020年；以及Limited Edition 2024，采用巴西、多米尼加与印尼烟叶，茄衣为墨西哥圣安德烈斯烟叶。

该品牌于2024年6月在柏林首次亮相，随后于2024年11月走进雅加达与万隆；2025年2月，苏西亚万在一次访谈中仍谈及此事。截至2026年9月，Cigarworld.de的目录中仍保留这三款规格。',
        '[{"name":"Courtisane","color":"#C9A96E","force":"Mild-Medium","wrapper":"未公开","vitolas":[],"story":"据品牌介绍，完全采用印尼烟草，带有木质、皮革、香草与咖啡的香气。"},{"name":"Java Exotica","color":"#A0522D","force":"Medium","wrapper":"爪哇（棕红色）","vitolas":[],"story":"采用多米尼加与巴西烟叶，茄衣为爪哇烟叶，首次采摘可追溯至2020年，据品牌介绍。"},{"name":"Limited Edition 2024","color":"#4A3728","force":null,"wrapper":"圣安德烈斯（墨西哥）","vitolas":[],"story":"采用巴西、多米尼加与印尼烟叶，茄衣为墨西哥圣安德烈斯烟叶；据品牌介绍带有泥土与巧克力的气息。"}]',
        'وُلدت Monsoon Cigar Company، بحسب الدار، من لقاء بين سوني سوسياوان وسيباستيان في مزرعة بمقاطعة براندنبورغ الألمانية؛ وأطلقت علامتها الأولى، Mata Hari، سنة 2024، في ألمانيا أولًا. والاسم مأخوذ من الراقصة الهولندية التي أُعدمت سنة 1917 بتهمة التجسس؛ ويقول سوسياوان إنه يريد التعريف بالسيجار الإندونيسي في الأسواق الدولية، بما فيها ألمانيا والولايات المتحدة.

لا تملك Monsoon مصنعًا خاصًا بها، ولا تكشف عن اسم المصنع الذي يُلفّ سجائرها. وتُعَدّ خلطاتها في جيمبر، شرق جاوة، بالتعاون مع PT Besuki Raya Cigar — الدار التي تقف خلف El Gaucho، الفرع التابع لمجموعة Mangli Djaya Raya منذ 2020 — حيث يقول سوسياوان إنه أشرف على جلسات تذوّق واختيار للورق. ويضمّ الكتالوج ثلاثة أصناف: Courtisane، المصنوعة بالكامل من تبغ إندونيسي بحسب الدار؛ وJava Exotica، من تبغ دومينيكي وبرازيلي تحت غلاف جاوي يعود أول قطاف له إلى 2020؛ وLimited Edition 2024، من تبغ برازيلي ودومينيكي وإندونيسي تحت غلاف سان أندريس مكسيكي.

قُدِّمت العلامة في برلين في يونيو 2024، ثم في جاكرتا وباندونغ في نوفمبر 2024؛ وما زال سوسياوان يتحدّث عنها في مقابلة أُجريت في فبراير 2025. وفي سبتمبر 2026، لا يزال موقع Cigarworld.de يعرض الأصناف الثلاثة في كتالوجه.',
        '[{"name":"Courtisane","color":"#C9A96E","force":"Mild-Medium","wrapper":"غير معلن","vitolas":[],"story":"مصنوعة بالكامل من تبغ إندونيسي بحسب الدار، التي تصف نكهاتها بالخشب والجلد والفانيليا والقهوة."},{"name":"Java Exotica","color":"#A0522D","force":"Medium","wrapper":"جاوة (كولورادو)","vitolas":[],"story":"تبغ دومينيكي وبرازيلي تحت غلاف جاوي يعود أول قطاف له إلى 2020، بحسب الدار."},{"name":"Limited Edition 2024","color":"#4A3728","force":null,"wrapper":"سان أندريس (المكسيك)","vitolas":[],"story":"تبغ برازيلي ودومينيكي وإندونيسي تحت غلاف سان أندريس مكسيكي؛ نكهات من التراب والشوكولاتة بحسب الدار."}]')
ON DUPLICATE KEY UPDATE `country_id` = VALUES(`country_id`), `founded` = VALUES(`founded`), `factory` = VALUES(`factory`), `source` = VALUES(`source`), `mentions` = VALUES(`mentions`), `history` = VALUES(`history`), `gamme` = VALUES(`gamme`), `history_en` = VALUES(`history_en`), `gamme_en` = VALUES(`gamme_en`), `history_es` = VALUES(`history_es`), `gamme_es` = VALUES(`gamme_es`), `history_de` = VALUES(`history_de`), `gamme_de` = VALUES(`gamme_de`), `history_zh` = VALUES(`history_zh`), `gamme_zh` = VALUES(`gamme_zh`), `history_ar` = VALUES(`history_ar`), `gamme_ar` = VALUES(`gamme_ar`);

-- ── Cuervo y Sobrinos ──
INSERT INTO `brands` (`name`, `country_id`, `founded`, `factory`, `source`, `mentions`, `history`, `gamme`, `history_en`, `gamme_en`, `history_es`, `gamme_es`, `history_de`, `gamme_de`, `history_zh`, `gamme_zh`, `history_ar`, `gamme_ar`)
VALUES ('Cuervo y Sobrinos',
        'nicaragua',
        '2023 — Cigar Conexion, Estelí',
        'Chez Tabacalera Pages, en partenariat avec Cigar Conexion, Estelí',
        'cuervoysobrinoscigars.com « History » (consulté 2026-09-24 : origine havanaise revendiquée par la maison, joaillerie de Ramón Fernández Cuervo en 1862, arrivée des six neveux en 1882, clientèle Hemingway et Churchill selon la maison, siège actuel à Capolago, Suisse) ; cuervoysobrinoscigars.com « Products » (consulté 2026-09-24 : cinq vitolas au catalogue — Toro, Mareva, Perfecto Press, Robusto, Historiador) ; cigarjournal.com « Cigar Conexion Launches the Cuervo y Sobrinos Cigars » (consulté 2026-09-24 : Cigar Conexion et Tabacalera Pages roulent les cigares à Estelí, tabac de graine cubaine, Fernando Navarro dirige Cigar Conexion) ; mystarluxury.pt « Cuervo y Sobrinos announces collaboration with Cigar Conexion » (2024-09-25 : annonce de la collaboration, fabrication à Estelí, tabac de graine cubaine)',
        NULL,
        'Cuervo y Sobrinos dit remonter à La Havane, où l''Asturien Ramón Fernández Cuervo ouvre une joaillerie en 1862 ; ses six neveux le rejoignent en 1882, année que la maison retient comme sa naissance officielle. Elle situe son âge d''or dans les années 1950 et dit avoir compté Caruso, Churchill, Einstein, Gable, Hemingway et Neruda parmi ses clients. La maison est aujourd''hui une horlogerie, avec siège et atelier à Capolago, en Suisse.

En 2023, Cuervo y Sobrinos ouvre une ligne de cigares confiée à Cigar Conexion, que dirige Fernando Navarro, en partenariat avec la Tabacalera Pages : les cigares, en tabac de graine cubaine, sont roulés à la main à Estelí, au Nicaragua. La maison ne dit pas comment les deux partenaires se partagent la fabrication. Le lancement se fait par étapes : le Japon en juin 2024, la Suisse en juillet, puis l''Europe, annoncée le 25 septembre 2024.

En septembre 2026, le site de la maison présente quatre vitolas — Toro, Mareva, Perfecto Press et Robusto — et une série à part, Historiador.',
        '[{"name":"Cuervo y Sobrinos","color":"#A0522D","force":null,"wrapper":"Non divulguée","vitolas":[],"story":"Tabac de graine cubaine roulé à la main à Estelí, en quatre vitolas : Toro, Mareva, Perfecto Press et Robusto."},{"name":"Historiador","color":"#6B4226","force":null,"wrapper":"Non divulguée","vitolas":[],"story":"Série à part au catalogue de la maison, qui n''en publie ni la cape ni la force."}]',
        'Cuervo y Sobrinos says it traces back to Havana, where the Asturian Ramón Fernández Cuervo opened a jewellery shop in 1862; his six nephews joined him in 1882, the year the house treats as its official founding. It places its golden age in the 1950s and says it counted Caruso, Churchill, Einstein, Gable, Hemingway and Neruda among its clients. The house is today a watchmaker, with its head office and workshop in Capolago, Switzerland.

In 2023, Cuervo y Sobrinos launched a cigar line entrusted to Cigar Conexion, led by Fernando Navarro, in partnership with Tabacalera Pages: the cigars, made with Cuban-seed tobacco, are hand-rolled in Estelí, Nicaragua. The house does not say how the two partners divide the manufacturing. The launch came in stages: Japan in June 2024, Switzerland in July, then Europe, announced on 25 September 2024.

In September 2026, the house''s website presented four vitolas — Toro, Mareva, Perfecto Press and Robusto — and a separate series, Historiador.',
        '[{"name":"Cuervo y Sobrinos","color":"#A0522D","force":null,"wrapper":"Undisclosed","vitolas":[],"story":"Cuban-seed tobacco hand-rolled in Estelí, in four vitolas: Toro, Mareva, Perfecto Press and Robusto."},{"name":"Historiador","color":"#6B4226","force":null,"wrapper":"Undisclosed","vitolas":[],"story":"A separate series in the house''s catalogue, for which it publishes neither the wrapper nor the strength."}]',
        'Cuervo y Sobrinos dice remontarse a La Habana, donde el asturiano Ramón Fernández Cuervo abre una joyería en 1862; sus seis sobrinos se le unen en 1882, año que la casa considera su nacimiento oficial. Sitúa su época dorada en los años 1950 y dice haber contado con Caruso, Churchill, Einstein, Gable, Hemingway y Neruda entre sus clientes. La casa es hoy una relojería, con sede y taller en Capolago, Suiza.

En 2023, Cuervo y Sobrinos abre una línea de puros confiada a Cigar Conexion, que dirige Fernando Navarro, en colaboración con Tabacalera Pages: los puros, de tabaco de semilla cubana, se lían a mano en Estelí, Nicaragua. La casa no dice cómo se reparten la fabricación los dos socios. El lanzamiento se hace por etapas: Japón en junio de 2024, Suiza en julio, y luego Europa, anunciada el 25 de septiembre de 2024.

En septiembre de 2026, el sitio de la casa presenta cuatro vitolas —Toro, Mareva, Perfecto Press y Robusto— y una serie aparte, Historiador.',
        '[{"name":"Cuervo y Sobrinos","color":"#A0522D","force":null,"wrapper":"No divulgada","vitolas":[],"story":"Tabaco de semilla cubana liado a mano en Estelí, en cuatro vitolas: Toro, Mareva, Perfecto Press y Robusto."},{"name":"Historiador","color":"#6B4226","force":null,"wrapper":"No divulgada","vitolas":[],"story":"Serie aparte en el catálogo de la casa, de la que no publica ni la capa ni la fuerza."}]',
        'Cuervo y Sobrinos führt sich nach eigenen Angaben auf Havanna zurück, wo der Asturier Ramón Fernández Cuervo 1862 ein Juweliergeschäft eröffnet; seine sechs Neffen stoßen 1882 zu ihm, das Jahr, das das Haus als seine offizielle Gründung ansieht. Es verortet sein goldenes Zeitalter in den 1950er-Jahren und gibt an, Caruso, Churchill, Einstein, Gable, Hemingway und Neruda zu seinen Kunden gezählt zu haben. Das Haus ist heute eine Uhrenmanufaktur mit Sitz und Werkstatt in Capolago, Schweiz.

2023 eröffnet Cuervo y Sobrinos eine Zigarrenlinie, die Cigar Conexion anvertraut wird, geleitet von Fernando Navarro, in Partnerschaft mit der Tabacalera Pages: Die Zigarren aus Tabak kubanischer Saatgutlinie werden in Estelí, Nicaragua, von Hand gerollt. Das Haus sagt nicht, wie sich die beiden Partner die Herstellung teilen. Die Einführung erfolgt in Etappen: Japan im Juni 2024, die Schweiz im Juli, dann Europa, angekündigt am 25. September 2024.

Im September 2026 stellt die Website des Hauses vier Formate vor — Toro, Mareva, Perfecto Press und Robusto — sowie eine eigene Serie, Historiador.',
        '[{"name":"Cuervo y Sobrinos","color":"#A0522D","force":null,"wrapper":"Nicht angegeben","vitolas":[],"story":"Tabak kubanischer Saatgutlinie, von Hand gerollt in Estelí, in vier Formaten: Toro, Mareva, Perfecto Press und Robusto."},{"name":"Historiador","color":"#6B4226","force":null,"wrapper":"Nicht angegeben","vitolas":[],"story":"Eine eigene Serie im Katalog des Hauses, zu der weder Deckblatt noch Stärke angegeben werden."}]',
        'Cuervo y Sobrinos自称可追溯至哈瓦那，阿斯图里亚斯人拉蒙·费尔南德斯·奎尔沃于1862年在那里开设了一家珠宝店；他的六个侄子于1882年加入，该品牌将这一年视为其正式创立之年。品牌将其黄金时代定位于二十世纪五十年代，并称卡鲁索、丘吉尔、爱因斯坦、盖博、海明威与聂鲁达都曾是其客户。如今，该品牌是一家制表企业，总部与工坊设于瑞士卡波拉戈。

2023年，Cuervo y Sobrinos推出雪茄产品线，交由费尔南多·纳瓦罗执掌的Cigar Conexion负责，并与Tabacalera Pages合作：这些雪茄采用古巴种子烟叶，在尼加拉瓜埃斯特利手工卷制。该品牌未说明两家合作方如何分工。产品分阶段上市：2024年6月登陆日本，7月登陆瑞士，随后是欧洲市场，于2024年9月25日宣布。

截至2026年9月，该品牌网站展示四款规格——Toro、Mareva、Perfecto Press与Robusto——以及一个独立系列Historiador。',
        '[{"name":"Cuervo y Sobrinos","color":"#A0522D","force":null,"wrapper":"未公开","vitolas":[],"story":"采用古巴种子烟叶，在埃斯特利手工卷制，共四款规格：Toro、Mareva、Perfecto Press与Robusto。"},{"name":"Historiador","color":"#6B4226","force":null,"wrapper":"未公开","vitolas":[],"story":"该品牌目录中的独立系列，未公开其茄衣与力度信息。"}]',
        'تقول Cuervo y Sobrinos إنها تعود إلى هافانا، حيث افتتح الأستوري رامون فرنانديز كويرفو محل مجوهرات سنة 1862؛ والتحق به أبناء إخوته الستة سنة 1882، وهي السنة التي تعتبرها الدار تاريخ تأسيسها الرسمي. وتضع عصرها الذهبي في خمسينيات القرن العشرين، وتقول إنها ضمّت كاروزو وتشرشل وأينشتاين وغيبل وهمنغواي ونيرودا إلى عملائها. والدار اليوم بيت لصناعة الساعات، ومقرّها وورشتها في كابولاغو بسويسرا.

في 2023، أطلقت Cuervo y Sobrinos خط سيجار عهدت به إلى Cigar Conexion، التي يديرها فرناندو نافارو، بشراكة مع Tabacalera Pages: وتُلفّ هذه السيجار، المصنوعة من تبغ بذرة كوبية، يدويًا في إستيلي بنيكاراغوا. ولا تقول الدار كيف يتقاسم الشريكان التصنيع. وجاء الإطلاق على مراحل: اليابان في يونيو 2024، ثم سويسرا في يوليو، ثم أوروبا التي أُعلن عنها في 25 سبتمبر 2024.

وفي سبتمبر 2026، يعرض موقع الدار أربعة أصناف — Toro وMareva وPerfecto Press وRobusto — وسلسلة منفصلة باسم Historiador.',
        '[{"name":"Cuervo y Sobrinos","color":"#A0522D","force":null,"wrapper":"غير معلن","vitolas":[],"story":"تبغ بذرة كوبية يُلفّ يدويًا في إستيلي، بأربعة أصناف: Toro وMareva وPerfecto Press وRobusto."},{"name":"Historiador","color":"#6B4226","force":null,"wrapper":"غير معلن","vitolas":[],"story":"سلسلة منفصلة في كتالوج الدار، لا تُعلن عن غلافها ولا عن قوّتها."}]')
ON DUPLICATE KEY UPDATE `country_id` = VALUES(`country_id`), `founded` = VALUES(`founded`), `factory` = VALUES(`factory`), `source` = VALUES(`source`), `mentions` = VALUES(`mentions`), `history` = VALUES(`history`), `gamme` = VALUES(`gamme`), `history_en` = VALUES(`history_en`), `gamme_en` = VALUES(`gamme_en`), `history_es` = VALUES(`history_es`), `gamme_es` = VALUES(`gamme_es`), `history_de` = VALUES(`history_de`), `gamme_de` = VALUES(`gamme_de`), `history_zh` = VALUES(`history_zh`), `gamme_zh` = VALUES(`gamme_zh`), `history_ar` = VALUES(`history_ar`), `gamme_ar` = VALUES(`gamme_ar`);

-- ── Ann-Eks ──
INSERT INTO `brands` (`name`, `country_id`, `founded`, `factory`, `source`, `mentions`, `history`, `gamme`, `history_en`, `gamme_en`, `history_es`, `gamme_es`, `history_de`, `gamme_de`, `history_zh`, `gamme_zh`, `history_ar`, `gamme_ar`)
VALUES ('Ann-Eks',
        'nicaragua',
        'Non précisée — August Schuster, Bünde',
        'Nicaragua — la maison ne nomme pas sa fabrique',
        'cigarworld.de « Ann-Eks: Zigarren, Zigarillos und Rum kaufen » (en allemand ; consulté le 24 septembre 2026 : gamme X — Günther en Toro et Gerda en Robusto —, tripe nicaraguayenne, sous-cape dominicaine, cape San Andrés claro du Mexique ; cigarillos Karla et Kurt d''origine brésilienne ; fabrique nicaraguayenne non nommée) ; zigarre.de « Ann-Eks » (en allemand ; consulté le 24 septembre 2026 : marque d''August Schuster GmbH & Co. KG, Bünde ; longfillers faits main dans une manufacture au Nicaragua, non nommée) ; paul-bugge.com « Ann-Eks Zigarren kaufen » (en allemand ; consulté le 24 septembre 2026 : confirme le classement Nicaragua de la gamme longfiller Ann-Eks X) ; cigarworld.de « Ann-Eks X Kurt (Panatella) » (consulté le 24 septembre 2026 : classe ce cigarillo shortfiller au Brésil, catégorie distincte de la gamme longfiller X du Nicaragua) ; cigarworld.de « Ann-Eks X » (consulté le 24 septembre 2026 : série au catalogue depuis le 28 décembre 2018 ; deux vitolas, Gerda et Günther, marquées TAM, entièrement roulées à la main)',
        NULL,
        'Ann-Eks est une marque d''August Schuster GmbH & Co. KG, maison de tabac de Bünde, en Rhénanie-du-Nord-Westphalie. Sous ce nom, la maison vend du rhum, des cigarillos d''origine brésilienne, Karla et Kurt, et une ligne de longfillers roulés entièrement à la main au Nicaragua, la ligne X, que Cigarworld.de tient au catalogue depuis le 28 décembre 2018. Elle compte deux vitolas, Gerda en Robusto et Günther en Toro, en tripe nicaraguayenne et sous-cape dominicaine sous une cape San Andrés claro du Mexique, dit Cigarworld.de.

La maison ne nomme pas la manufacture qui roule la ligne X, ni la ville où elle se trouve. Elle vend aussi Canned Heat, un Nicaragua puro en boîte métallique individuelle. En septembre 2026, la ligne X est en vente chez Zigarre.de, Cigarworld.de et Paul-Bugge.com.',
        '[{"name":"Ann-Eks X","color":"#A0522D","force":null,"wrapper":"San Andrés claro (Mexique)","vitolas":[],"story":"Tripe nicaraguayenne et sous-cape dominicaine sous cape San Andrés claro du Mexique, en deux vitolas, Gerda (Robusto) et Günther (Toro), dit Cigarworld.de."}]',
        'Ann-Eks is a brand of August Schuster GmbH & Co. KG, a tobacco house from Bünde, in North Rhine-Westphalia. Under this name, the house sells rum, cigarillos of Brazilian origin, Karla and Kurt, and a line of longfillers rolled entirely by hand in Nicaragua, the X line, which Cigarworld.de has carried in its catalogue since 28 December 2018. It comprises two vitolas, Gerda in Robusto and Günther in Toro, with Nicaraguan filler and Dominican binder under a Mexican San Andrés claro wrapper, says Cigarworld.de.

The house does not name the factory that rolls the X line, nor the town where it is located. It also sells Canned Heat, a Nicaragua puro in an individual tin. As of September 2026, the X line is on sale at Zigarre.de, Cigarworld.de and Paul-Bugge.com.',
        '[{"name":"Ann-Eks X","color":"#A0522D","force":null,"wrapper":"San Andrés claro (Mexico)","vitolas":[],"story":"Nicaraguan filler and Dominican binder under a Mexican San Andrés claro wrapper, in two vitolas, Gerda (Robusto) and Günther (Toro), says Cigarworld.de."}]',
        'Ann-Eks es una marca de August Schuster GmbH & Co. KG, casa tabaquera de Bünde, en Renania del Norte-Westfalia. Bajo este nombre, la casa vende ron, cigarritos de origen brasileño, Karla y Kurt, y una línea de longfillers torcidos enteramente a mano en Nicaragua, la línea X, que Cigarworld.de mantiene en catálogo desde el 28 de diciembre de 2018. Cuenta con dos vitolas, Gerda en Robusto y Günther en Toro, con tripa nicaragüense y capote dominicano bajo una capa San Andrés claro de México, según Cigarworld.de.

La casa no nombra la fábrica que tuerce la línea X, ni la ciudad donde se encuentra. También vende Canned Heat, un Nicaragua puro en lata individual. En septiembre de 2026, la línea X está a la venta en Zigarre.de, Cigarworld.de y Paul-Bugge.com.',
        '[{"name":"Ann-Eks X","color":"#A0522D","force":null,"wrapper":"San Andrés claro (México)","vitolas":[],"story":"Tripa nicaragüense y capote dominicano bajo capa San Andrés claro de México, en dos vitolas, Gerda (Robusto) y Günther (Toro), según Cigarworld.de."}]',
        'Ann-Eks ist eine Marke der August Schuster GmbH & Co. KG, eines Tabakhauses aus Bünde in Nordrhein-Westfalen. Unter diesem Namen verkauft das Haus Rum, Zigarillos brasilianischen Ursprungs, Karla und Kurt, sowie eine Linie von Longfillern, die vollständig von Hand in Nicaragua gedreht werden, die Linie X, die Cigarworld.de seit dem 28. Dezember 2018 im Katalog führt. Sie umfasst zwei Vitolas, Gerda als Robusto und Günther als Toro, mit nicaraguanischer Einlage und dominikanischem Umblatt unter einem mexikanischen San-Andrés-claro-Deckblatt, so Cigarworld.de.

Das Haus nennt weder die Fabrik, die die Linie X dreht, noch die Stadt, in der sie sich befindet. Es verkauft auch Canned Heat, einen Nicaragua puro in einer einzelnen Blechdose. Im September 2026 ist die Linie X bei Zigarre.de, Cigarworld.de und Paul-Bugge.com erhältlich.',
        '[{"name":"Ann-Eks X","color":"#A0522D","force":null,"wrapper":"San Andrés claro (Mexiko)","vitolas":[],"story":"Nicaraguanische Einlage und dominikanisches Umblatt unter einem mexikanischen San-Andrés-claro-Deckblatt, in zwei Vitolas, Gerda (Robusto) und Günther (Toro), so Cigarworld.de."}]',
        'Ann-Eks是August Schuster GmbH & Co. KG旗下的一个品牌，这是一家位于北莱茵-威斯特法伦州Bünde的烟草商行。该商行以此名义出售朗姆酒、产自巴西的小雪茄Karla与Kurt，以及一条在尼加拉瓜完全手工卷制的longfiller系列——X系列，Cigarworld.de自2018年12月28日起将其列入目录。该系列有两款规格，Gerda为Robusto，Günther为Toro，采用尼加拉瓜茄芯与多米尼加茄套，外覆墨西哥San Andrés claro茄衣，Cigarworld.de如是说。

该商行未透露卷制X系列的工厂名称，也未透露其所在城市。该商行还出售Canned Heat，一款尼加拉瓜puro，装在独立金属罐中。截至2026年9月，X系列在Zigarre.de、Cigarworld.de与Paul-Bugge.com有售。',
        '[{"name":"Ann-Eks X","color":"#A0522D","force":null,"wrapper":"San Andrés claro（墨西哥）","vitolas":[],"story":"尼加拉瓜茄芯与多米尼加茄套，外覆墨西哥San Andrés claro茄衣，两款规格为Gerda（Robusto）与Günther（Toro），Cigarworld.de如是说。"}]',
        'Ann-Eks علامة تابعة لشركة August Schuster GmbH & Co. KG، دار تبغ من Bünde في شمال الراين-وستفاليا. تحت هذا الاسم، تبيع الدار الروم، وسيجارين صغيرين من أصل برازيلي هما Karla وKurt، وسلسلة سيجار longfiller يُلَفّ بالكامل يدويًا في نيكاراغوا، هي سلسلة X، التي تدرجها Cigarworld.de في كتالوجها منذ 28 ديسمبر 2018. وتضم هذه السلسلة مقاسين هما Gerda بمقاس Robusto وGünther بمقاس Toro، بحشوة نيكاراغوية وغلاف داخلي دومينيكاني تحت غلاف San Andrés claro مكسيكي، بحسب Cigarworld.de.

لا تكشف الدار عن اسم المصنع الذي يلفّ سلسلة X، ولا عن المدينة التي يقع فيها. كما تبيع الدار Canned Heat، وهو سيجار نيكاراغوا puro يُباع في علبة معدنية فردية. وحتى سبتمبر 2026، سلسلة X معروضة للبيع لدى Zigarre.de وCigarworld.de وPaul-Bugge.com.',
        '[{"name":"Ann-Eks X","color":"#A0522D","force":null,"wrapper":"San Andrés claro (المكسيك)","vitolas":[],"story":"حشوة نيكاراغوية وغلاف داخلي دومينيكاني تحت غلاف San Andrés claro مكسيكي، بمقاسين هما Gerda (Robusto) وGünther (Toro)، بحسب Cigarworld.de."}]')
ON DUPLICATE KEY UPDATE `country_id` = VALUES(`country_id`), `founded` = VALUES(`founded`), `factory` = VALUES(`factory`), `source` = VALUES(`source`), `mentions` = VALUES(`mentions`), `history` = VALUES(`history`), `gamme` = VALUES(`gamme`), `history_en` = VALUES(`history_en`), `gamme_en` = VALUES(`gamme_en`), `history_es` = VALUES(`history_es`), `gamme_es` = VALUES(`gamme_es`), `history_de` = VALUES(`history_de`), `gamme_de` = VALUES(`gamme_de`), `history_zh` = VALUES(`history_zh`), `gamme_zh` = VALUES(`gamme_zh`), `history_ar` = VALUES(`history_ar`), `gamme_ar` = VALUES(`gamme_ar`);

-- ── BerlinCigarMen ──
INSERT INTO `brands` (`name`, `country_id`, `founded`, `factory`, `source`, `mentions`, `history`, `gamme`, `history_en`, `gamme_en`, `history_es`, `gamme_es`, `history_de`, `gamme_de`, `history_zh`, `gamme_zh`, `history_ar`, `gamme_ar`)
VALUES ('BerlinCigarMen',
        'nicaragua',
        '2014 — idée d''Olaf Hartmannsgruber, Berlin',
        'Nicaragua — la maison ne nomme pas sa fabrique',
        'noblego.de « Die BERLINCIGARMEN eins jetzt auf Noblego.de online kaufen » (en allemand ; consulté le 24 septembre 2026 : cigare né d''une idée de 2014 d''Olaf Hartmannsgruber pour un festival de rue de la communauté gay de Berlin ; format Double Toro de 165 mm sur 64 de cepo ; tripe de tabacs du Nicaragua et de République dominicaine vieillis jusqu''à cinq ans, cape et sous-cape du Nicaragua ; fabrique non nommée) ; eventartdirection.de « EVENTARTDIRECTION » (consulté le 24 septembre 2026 : société berlinoise d''Olaf Hartmannsgruber, à l''origine du cigare BerlinCigarMen) ; cigarworld.de « BerlinCigarMen: Zigarren kaufen » (consulté le 24 septembre 2026 : classe le cigare Eins au Nicaragua ; situe le collectif au bar Pussycat, quartier de Schöneberg-Nollendorf à Berlin, réuni chaque mois)',
        NULL,
        'BerlinCigarMen est un collectif d''amateurs de cigares de la communauté gay de Berlin, qui se réunit chaque mois au bar Pussycat, dans le quartier de Schöneberg-Nollendorf, dit Cigarworld.de. L''idée d''un cigare à son nom remonte à 2014 : Olaf Hartmannsgruber la conçoit pour un festival de rue de la communauté gay de la ville, dit Noblego.de, et sa société, EVENTARTDIRECTION, porte le projet. Le résultat est un format unique nommé Eins, mot allemand pour un : un longfiller Double Toro de 165 mm sur 64 de cepo, en tripe de tabacs du Nicaragua et de République dominicaine vieillis jusqu''à cinq ans, sous cape et sous-cape nicaraguayennes.

La maison ne nomme pas la fabrique qui roule le Eins au Nicaragua, ni la ville où elle se trouve. En septembre 2026, le cigare est en vente chez Noblego.de et Cigarworld.de, à l''unité ou en coffret de bois massif ; c''est l''unique référence de la marque.',
        '[{"name":"Eins","color":"#A0522D","force":"Medium","wrapper":"Nicaragua","vitolas":[],"story":"Longfiller Double Toro de 165 mm sur 64 de cepo, tripe de tabacs du Nicaragua et de République dominicaine vieillis jusqu''à cinq ans sous cape et sous-cape nicaraguayennes, de force moyenne, dit Noblego.de."}]',
        'BerlinCigarMen is a collective of cigar enthusiasts from Berlin''s gay community, who meet every month at the Pussycat bar, in the Schöneberg-Nollendorf district, says Cigarworld.de. The idea for a cigar bearing its name dates back to 2014: Olaf Hartmannsgruber conceived it for the city''s gay community street festival, says Noblego.de, and his company, EVENTARTDIRECTION, carries the project. The result is a unique format named Eins, German for one: a Double Toro longfiller measuring 165 mm with a 64 ring gauge, with filler tobaccos from Nicaragua and the Dominican Republic aged up to five years, under a Nicaraguan wrapper and binder.

The house does not name the factory that rolls the Eins in Nicaragua, nor the town where it is located. As of September 2026, the cigar is on sale at Noblego.de and Cigarworld.de, singly or in a solid wood box; it is the brand''s only reference.',
        '[{"name":"Eins","color":"#A0522D","force":"Medium","wrapper":"Nicaragua","vitolas":[],"story":"A Double Toro longfiller measuring 165 mm with a 64 ring gauge, filler tobaccos from Nicaragua and the Dominican Republic aged up to five years under a Nicaraguan wrapper and binder, medium in strength, says Noblego.de."}]',
        'BerlinCigarMen es un colectivo de aficionados al puro de la comunidad gay de Berlín, que se reúne cada mes en el bar Pussycat, en el barrio de Schöneberg-Nollendorf, según Cigarworld.de. La idea de un puro con su nombre se remonta a 2014: Olaf Hartmannsgruber la concibe para un festival callejero de la comunidad gay de la ciudad, según Noblego.de, y su empresa, EVENTARTDIRECTION, lleva adelante el proyecto. El resultado es un formato único llamado Eins, palabra alemana para uno: un longfiller Double Toro de 165 mm por 64 de cepo, con tripa de tabacos de Nicaragua y República Dominicana añejados hasta cinco años, bajo capa y capote nicaragüenses.

La casa no nombra la fábrica que tuerce el Eins en Nicaragua, ni la ciudad donde se encuentra. En septiembre de 2026, el puro está a la venta en Noblego.de y Cigarworld.de, por unidad o en caja de madera maciza; es la única referencia de la marca.',
        '[{"name":"Eins","color":"#A0522D","force":"Medium","wrapper":"Nicaragua","vitolas":[],"story":"Longfiller Double Toro de 165 mm por 64 de cepo, tripa de tabacos de Nicaragua y República Dominicana añejados hasta cinco años bajo capa y capote nicaragüenses, de fuerza media, según Noblego.de."}]',
        'BerlinCigarMen ist ein Kollektiv von Zigarrenliebhabern aus der Berliner Schwulen-Community, das sich jeden Monat in der Bar Pussycat im Viertel Schöneberg-Nollendorf trifft, so Cigarworld.de. Die Idee zu einer Zigarre mit diesem Namen geht auf das Jahr 2014 zurück: Olaf Hartmannsgruber entwickelt sie für ein Straßenfest der Schwulen-Community der Stadt, so Noblego.de, und seine Firma EVENTARTDIRECTION trägt das Projekt. Das Ergebnis ist ein einzigartiges Format mit dem Namen Eins: ein Longfiller der Sorte Double Toro mit 165 mm Länge und Ringmaß 64, mit einer Einlage aus bis zu fünf Jahre gelagerten Tabaken aus Nicaragua und der Dominikanischen Republik unter nicaraguanischem Deckblatt und Umblatt.

Das Haus nennt weder die Fabrik, die den Eins in Nicaragua dreht, noch die Stadt, in der sie sich befindet. Im September 2026 ist die Zigarre bei Noblego.de und Cigarworld.de erhältlich, einzeln oder in einer Kiste aus massivem Holz; sie ist die einzige Referenz der Marke.',
        '[{"name":"Eins","color":"#A0522D","force":"Medium","wrapper":"Nicaragua","vitolas":[],"story":"Longfiller der Sorte Double Toro mit 165 mm Länge und Ringmaß 64, Einlage aus bis zu fünf Jahre gelagerten Tabaken aus Nicaragua und der Dominikanischen Republik unter nicaraguanischem Deckblatt und Umblatt, mittlerer Stärke, so Noblego.de."}]',
        'BerlinCigarMen是柏林同志群体中一个雪茄迷的团体，据Cigarworld.de介绍，该团体每月在Schöneberg-Nollendorf区的Pussycat酒吧聚会。以其名字命名雪茄的想法可追溯到2014年：据Noblego.de介绍，Olaf Hartmannsgruber为该市同志群体的一个街头节构思了这一方案，他的公司EVENTARTDIRECTION负责推进这个项目。成果是一款独特规格，命名为Eins，是德语中数字一的说法：一支165毫米、环径64的Double Toro longfiller，茄芯采用陈化长达五年的尼加拉瓜与多米尼加烟叶，外覆尼加拉瓜茄衣与茄套。

该商行未透露在尼加拉瓜卷制Eins的工厂名称，也未透露其所在城市。截至2026年9月，这款雪茄在Noblego.de与Cigarworld.de有售，可单支购买，也可选购实木礼盒装；这是该品牌唯一的产品。',
        '[{"name":"Eins","color":"#A0522D","force":"Medium","wrapper":"尼加拉瓜","vitolas":[],"story":"Double Toro longfiller，165毫米，环径64，茄芯采用陈化长达五年的尼加拉瓜与多米尼加烟叶，外覆尼加拉瓜茄衣与茄套，力度适中，Noblego.de如是说。"}]',
        'BerlinCigarMen مجموعة من هواة السيجار من مجتمع المثليين في برلين، تجتمع كل شهر في حانة Pussycat، في حي Schöneberg-Nollendorf، بحسب Cigarworld.de. تعود فكرة سيجار يحمل اسمها إلى عام 2014: تصورها Olaf Hartmannsgruber من أجل مهرجان شوارع لمجتمع المثليين في المدينة، بحسب Noblego.de، وتتولى شركته EVENTARTDIRECTION تنفيذ المشروع. والنتيجة سيجار فريد المقاس يحمل اسم Eins، وهي الكلمة الألمانية التي تعني واحد: سيجار longfiller بمقاس Double Toro طوله 165 ملم وقياس حلقته 64، بحشوة من تبغ نيكاراغوا وجمهورية الدومينيكان معتَّق حتى خمس سنوات، تحت غلاف وغلاف داخلي نيكاراغويين.

لا تكشف الدار عن اسم المصنع الذي يلفّ Eins في نيكاراغوا، ولا عن المدينة التي يقع فيها. وحتى سبتمبر 2026، السيجار معروض للبيع لدى Noblego.de وCigarworld.de، إما بالقطعة أو في علبة من خشب مصمت؛ وهو المنتج الوحيد للعلامة.',
        '[{"name":"Eins","color":"#A0522D","force":"Medium","wrapper":"نيكاراغوا","vitolas":[],"story":"سيجار longfiller بمقاس Double Toro طوله 165 ملم وقياس حلقته 64، بحشوة من تبغ نيكاراغوا وجمهورية الدومينيكان معتَّق حتى خمس سنوات تحت غلاف وغلاف داخلي نيكاراغويين، متوسط القوة، بحسب Noblego.de."}]')
ON DUPLICATE KEY UPDATE `country_id` = VALUES(`country_id`), `founded` = VALUES(`founded`), `factory` = VALUES(`factory`), `source` = VALUES(`source`), `mentions` = VALUES(`mentions`), `history` = VALUES(`history`), `gamme` = VALUES(`gamme`), `history_en` = VALUES(`history_en`), `gamme_en` = VALUES(`gamme_en`), `history_es` = VALUES(`history_es`), `gamme_es` = VALUES(`gamme_es`), `history_de` = VALUES(`history_de`), `gamme_de` = VALUES(`gamme_de`), `history_zh` = VALUES(`history_zh`), `gamme_zh` = VALUES(`gamme_zh`), `history_ar` = VALUES(`history_ar`), `gamme_ar` = VALUES(`gamme_ar`);

-- ── Canned Heat ──
INSERT INTO `brands` (`name`, `country_id`, `founded`, `factory`, `source`, `mentions`, `history`, `gamme`, `history_en`, `gamme_en`, `history_es`, `gamme_es`, `history_de`, `gamme_de`, `history_zh`, `gamme_zh`, `history_ar`, `gamme_ar`)
VALUES ('Canned Heat',
        'nicaragua',
        'Non précisée — Philipp Schuster, Bünde',
        'Nicaragua — la maison ne nomme pas sa fabrique',
        'zigarrennewsblog.ch « Canned Heat Robusto » (en allemand ; consulté le 24 septembre 2026 : cigare fait faire par Philipp Schuster, maison familiale établie dans le tabac depuis plus de cent ans à Bünde ; Nicaragua puro — cape maduro, sous-cape et tripe du pays, assemblage incluant du tabac ligero — roulé main, conditionné en boîte métallique ; fabrique non nommée) ; cigarworld.de « Canned Heat Longfiller » (consulté le 24 septembre 2026 : gamme Longfiller — Gran Robusto et Robusto — introduite le 9 octobre 2015, entièrement roulée à la main ; fabrique non nommée) ; paul-bugge.com « Canned Heat Zigarren kaufen » (en allemand ; consulté le 24 septembre 2026 : confirme le classement Nicaragua et la fabrication artisanale ; fabrique non nommée)',
        NULL,
        'Canned Heat est un cigare que fait faire Philipp Schuster, de la maison familiale August Schuster GmbH & Co. KG, établie dans le tabac à Bünde depuis plus d''un siècle — la maison qui vend aussi Ann-Eks. C''est un Nicaragua puro roulé entièrement à la main : cape maduro, sous-cape et tripe du pays, avec du ligero dans l''assemblage. Chaque cigare se vend dans une boîte métallique individuelle, une conserve ; trouver l''humidité qui laisse le tabac mûrir en milieu hermétique a demandé un long travail, dit la maison.

La ligne Longfiller, en Robusto et Gran Robusto, est au catalogue de Cigarworld.de depuis le 9 octobre 2015. La maison ne nomme pas la fabrique qui la roule au Nicaragua, ni la ville où elle se trouve. En septembre 2026, Canned Heat est en vente chez Cigarworld.de et Paul-Bugge.com.',
        '[{"name":"Longfiller","color":"#4A3728","force":null,"wrapper":"Maduro (Nicaragua)","vitolas":[],"story":"Nicaragua puro sous cape maduro, en Robusto et Gran Robusto, chaque cigare dans sa boîte métallique."}]',
        'Canned Heat is a cigar commissioned by Philipp Schuster, of the family house August Schuster GmbH & Co. KG, established in the tobacco trade in Bünde for more than a century — the house that also sells Ann-Eks. It is a Nicaragua puro rolled entirely by hand: maduro wrapper, binder and filler from the country, with ligero in the blend. Each cigar is sold in an individual metal tin, a can; finding the humidity that lets the tobacco mature in an airtight environment took a long time, says the house.

The Longfiller line, in Robusto and Gran Robusto, has been in Cigarworld.de''s catalogue since 9 October 2015. The house does not name the factory that rolls it in Nicaragua, nor the town where it is located. As of September 2026, Canned Heat is on sale at Cigarworld.de and Paul-Bugge.com.',
        '[{"name":"Longfiller","color":"#4A3728","force":null,"wrapper":"Maduro (Nicaragua)","vitolas":[],"story":"Nicaragua puro under a maduro wrapper, in Robusto and Gran Robusto, each cigar in its own tin."}]',
        'Canned Heat es un puro que encarga Philipp Schuster, de la casa familiar August Schuster GmbH & Co. KG, establecida en el tabaco en Bünde desde hace más de un siglo — la casa que también vende Ann-Eks. Es un Nicaragua puro torcido enteramente a mano: capa maduro, capote y tripa del país, con ligero en la mezcla. Cada puro se vende en una lata metálica individual, una conserva; encontrar la humedad que permite que el tabaco madure en un entorno hermético exigió un largo trabajo, según la casa.

La línea Longfiller, en Robusto y Gran Robusto, está en el catálogo de Cigarworld.de desde el 9 de octubre de 2015. La casa no nombra la fábrica que la tuerce en Nicaragua, ni la ciudad donde se encuentra. En septiembre de 2026, Canned Heat está a la venta en Cigarworld.de y Paul-Bugge.com.',
        '[{"name":"Longfiller","color":"#4A3728","force":null,"wrapper":"Maduro (Nicaragua)","vitolas":[],"story":"Nicaragua puro bajo capa maduro, en Robusto y Gran Robusto, cada puro en su lata."}]',
        'Canned Heat ist eine Zigarre, die Philipp Schuster in Auftrag gibt, vom Familienunternehmen August Schuster GmbH & Co. KG, seit mehr als einem Jahrhundert im Tabakgeschäft in Bünde ansässig — dem Haus, das auch Ann-Eks verkauft. Es handelt sich um einen Nicaragua puro, vollständig von Hand gedreht: Deckblatt maduro, Umblatt und Einlage aus dem Land, mit ligero in der Mischung. Jede Zigarre wird in einer einzelnen Blechdose verkauft, einer Konserve; die richtige Luftfeuchtigkeit zu finden, bei der der Tabak in einer hermetisch verschlossenen Umgebung reifen kann, erforderte lange Arbeit, so das Haus.

Die Linie Longfiller, in Robusto und Gran Robusto, ist seit dem 9. Oktober 2015 im Katalog von Cigarworld.de. Das Haus nennt weder die Fabrik, die sie in Nicaragua dreht, noch die Stadt, in der sie sich befindet. Im September 2026 ist Canned Heat bei Cigarworld.de und Paul-Bugge.com erhältlich.',
        '[{"name":"Longfiller","color":"#4A3728","force":null,"wrapper":"Maduro (Nicaragua)","vitolas":[],"story":"Nicaragua puro unter Deckblatt maduro, in Robusto und Gran Robusto, jede Zigarre in ihrer eigenen Blechdose."}]',
        'Canned Heat是Philipp Schuster委托制作的一款雪茄，来自在Bünde经营烟草生意已逾一个世纪的家族商行August Schuster GmbH & Co. KG——该商行也出售Ann-Eks。这是一款完全手工卷制的尼加拉瓜puro：maduro茄衣，本国产茄套与茄芯，配方中加入ligero。每支雪茄都装在独立的金属罐中——一个罐头；据商行介绍，找到能让烟叶在密闭环境中陈化的湿度，是一项漫长的工作。

Longfiller系列，有Robusto与Gran Robusto两种规格，自2015年10月9日起被Cigarworld.de列入目录。该商行未透露在尼加拉瓜卷制该系列的工厂名称，也未透露其所在城市。截至2026年9月，Canned Heat在Cigarworld.de与Paul-Bugge.com有售。',
        '[{"name":"Longfiller","color":"#4A3728","force":null,"wrapper":"Maduro（尼加拉瓜）","vitolas":[],"story":"尼加拉瓜puro，外覆maduro茄衣，有Robusto与Gran Robusto两种规格，每支雪茄均装在独立金属罐中。"}]',
        'Canned Heat سيجار يكلّف بصنعه Philipp Schuster، من الدار العائلية August Schuster GmbH & Co. KG، العاملة في التبغ في Bünde منذ ما يزيد على قرن — وهي الدار التي تبيع أيضًا Ann-Eks. إنه سيجار نيكاراغوا puro يُلَفّ بالكامل يدويًا: غلاف maduro، وغلاف داخلي وحشوة من البلد نفسه، مع ligero ضمن المزيج. يُباع كل سيجار في علبة معدنية فردية، أي معلبة؛ وقد تطلّب إيجاد درجة الرطوبة التي تتيح للتبغ أن ينضج في بيئة محكمة الإغلاق عملًا طويلاً، بحسب الدار.

أُدرجت سلسلة Longfiller، بمقاسي Robusto وGran Robusto، في كتالوج Cigarworld.de منذ 9 أكتوبر 2015. ولا تكشف الدار عن اسم المصنع الذي يلفّها في نيكاراغوا، ولا عن المدينة التي يقع فيها. وحتى سبتمبر 2026، Canned Heat معروض للبيع لدى Cigarworld.de وPaul-Bugge.com.',
        '[{"name":"Longfiller","color":"#4A3728","force":null,"wrapper":"Maduro (نيكاراغوا)","vitolas":[],"story":"سيجار نيكاراغوا puro تحت غلاف maduro، بمقاسي Robusto وGran Robusto، كل سيجار في علبته المعدنية الخاصة."}]')
ON DUPLICATE KEY UPDATE `country_id` = VALUES(`country_id`), `founded` = VALUES(`founded`), `factory` = VALUES(`factory`), `source` = VALUES(`source`), `mentions` = VALUES(`mentions`), `history` = VALUES(`history`), `gamme` = VALUES(`gamme`), `history_en` = VALUES(`history_en`), `gamme_en` = VALUES(`gamme_en`), `history_es` = VALUES(`history_es`), `gamme_es` = VALUES(`gamme_es`), `history_de` = VALUES(`history_de`), `gamme_de` = VALUES(`gamme_de`), `history_zh` = VALUES(`history_zh`), `gamme_zh` = VALUES(`gamme_zh`), `history_ar` = VALUES(`history_ar`), `gamme_ar` = VALUES(`gamme_ar`);

-- ── Casa Culinaria ──
INSERT INTO `brands` (`name`, `country_id`, `founded`, `factory`, `source`, `mentions`, `history`, `gamme`, `history_en`, `gamme_en`, `history_es`, `gamme_es`, `history_de`, `gamme_de`, `history_zh`, `gamme_zh`, `history_ar`, `gamme_ar`)
VALUES ('Casa Culinaria',
        'nicaragua',
        'Non précisée — Paul Bugge, Villingen-Schwenningen',
        'Nicaragua — la maison ne nomme pas sa fabrique',
        'cigar-wiki.com « Casa Culinaria » (en allemand ; consulté le 24 septembre 2026 : trois séries — Connecticut à cape dorée des États-Unis, Esteli et Jalapa à capes nicaraguayennes —, façonnées à la main au Nicaragua ; fabrique non nommée) ; cigarworld.de « Casa Culinaria » (consulté le 24 septembre 2026 : marque originaire de Bade conçue par Paul Bugge à Villingen-Schwenningen, produite entièrement au Nicaragua ; Connecticut succède à une série Orange, Esteli à une série Red Fort, les séries portaient à l''origine des noms de couleurs ; fabrique non nommée) ; paul-bugge.com « Casa Culinaria Zigarren kaufen » (en allemand ; consulté le 24 septembre 2026 : trois séries en vente — Connecticut de force légère, Jalapa de force moyenne à tabac de la région du même nom, Esteli de force corsée à cape huileuse foncée —, toutes façonnées à la main au Nicaragua, fabrique non nommée)',
        NULL,
        'Casa Culinaria est une marque de Paul Bugge, négociant en cigares de Villingen-Schwenningen, en Forêt-Noire ; la maison ne date pas sa création. Ses séries portaient à l''origine des noms de couleurs, dit Cigarworld.de ; en septembre 2026, le catalogue en compte trois. Connecticut, de force légère selon la maison, porte une cape dorée des États-Unis sur un cœur de tabacs nicaraguayens ; elle a succédé à une série nommée Orange. Jalapa, de force moyenne, tire son nom de la région du Nicaragua d''où vient l''essentiel du tabac, cape comprise. Esteli, de force corsée, à la cape huileuse et foncée, poursuit une série antérieure appelée Red Fort.

Toutes les séries sont façonnées à la main au Nicaragua ; la maison ne nomme pas la fabrique qui les roule, ni la ville où elle se trouve. En septembre 2026, Casa Culinaria est en vente chez Paul-Bugge.com et Cigarworld.de.',
        '[{"name":"Connecticut","color":"#C9A96E","force":"Mild","wrapper":"Connecticut (États-Unis)","vitolas":[],"story":"Cœur de tabacs nicaraguayens sous cape américaine, succède à une ancienne série Orange, dit la maison."},{"name":"Jalapa","color":"#8B5A2B","force":"Medium","wrapper":"Nicaragua","vitolas":[],"story":"Tabac entièrement nicaraguayen de la région de Jalapa, qui donne son nom à la série, dit la maison."},{"name":"Esteli","color":"#4A3728","force":"Medium-Full","wrapper":"Nicaragua","vitolas":[],"story":"Cape huileuse et foncée, tabacs de la région d''Esteli, dans la continuité d''une ancienne série Red Fort, dit la maison."}]',
        'Casa Culinaria is a brand of Paul Bugge, a cigar merchant from Villingen-Schwenningen, in the Black Forest; the house does not date its founding. Its series originally bore colour names, says Cigarworld.de; as of September 2026, the catalogue includes three. Connecticut, mild in strength according to the house, wears a golden American wrapper over a heart of Nicaraguan tobaccos; it succeeded a series named Orange. Jalapa, medium in strength, takes its name from the Nicaraguan region that supplies most of its tobacco, wrapper included. Esteli, full-bodied, with an oily, dark wrapper, continues an earlier series called Red Fort.

All the series are hand-crafted in Nicaragua; the house does not name the factory that rolls them, nor the town where it is located. As of September 2026, Casa Culinaria is on sale at Paul-Bugge.com and Cigarworld.de.',
        '[{"name":"Connecticut","color":"#C9A96E","force":"Mild","wrapper":"Connecticut (United States)","vitolas":[],"story":"A heart of Nicaraguan tobaccos under an American wrapper, succeeding an earlier Orange series, says the house."},{"name":"Jalapa","color":"#8B5A2B","force":"Medium","wrapper":"Nicaragua","vitolas":[],"story":"Tobacco entirely from Nicaragua''s Jalapa region, which gives the series its name, says the house."},{"name":"Esteli","color":"#4A3728","force":"Medium-Full","wrapper":"Nicaragua","vitolas":[],"story":"An oily, dark wrapper, tobaccos from the Esteli region, continuing on from an earlier Red Fort series, says the house."}]',
        'Casa Culinaria es una marca de Paul Bugge, comerciante de puros de Villingen-Schwenningen, en la Selva Negra; la casa no data su creación. Sus series llevaban originalmente nombres de colores, según Cigarworld.de; en septiembre de 2026, el catálogo cuenta con tres. Connecticut, de fuerza suave según la casa, luce una capa dorada estadounidense sobre un corazón de tabacos nicaragüenses; sucedió a una serie llamada Orange. Jalapa, de fuerza media, toma su nombre de la región de Nicaragua de donde procede la mayor parte de su tabaco, capa incluida. Esteli, de fuerza intensa, de capa aceitosa y oscura, da continuidad a una serie anterior llamada Red Fort.

Todas las series se elaboran a mano en Nicaragua; la casa no nombra la fábrica que las tuerce, ni la ciudad donde se encuentra. En septiembre de 2026, Casa Culinaria está a la venta en Paul-Bugge.com y Cigarworld.de.',
        '[{"name":"Connecticut","color":"#C9A96E","force":"Mild","wrapper":"Connecticut (Estados Unidos)","vitolas":[],"story":"Corazón de tabacos nicaragüenses bajo capa estadounidense, sucede a una antigua serie Orange, según la casa."},{"name":"Jalapa","color":"#8B5A2B","force":"Medium","wrapper":"Nicaragua","vitolas":[],"story":"Tabaco enteramente nicaragüense de la región de Jalapa, que da nombre a la serie, según la casa."},{"name":"Esteli","color":"#4A3728","force":"Medium-Full","wrapper":"Nicaragua","vitolas":[],"story":"Capa aceitosa y oscura, tabacos de la región de Esteli, en la continuidad de una antigua serie Red Fort, según la casa."}]',
        'Casa Culinaria ist eine Marke von Paul Bugge, einem Zigarrenhändler aus Villingen-Schwenningen im Schwarzwald; das Haus datiert seine Gründung nicht. Seine Serien trugen ursprünglich Farbnamen, so Cigarworld.de; im September 2026 umfasst der Katalog drei davon. Connecticut, laut dem Haus von milder Stärke, trägt ein goldenes amerikanisches Deckblatt über einem Herzen aus nicaraguanischen Tabaken; sie folgte auf eine Serie namens Orange. Jalapa, mittlerer Stärke, verdankt ihren Namen der nicaraguanischen Region, aus der der Großteil ihres Tabaks stammt, Deckblatt eingeschlossen. Esteli, kräftiger Stärke, mit öligem, dunklem Deckblatt, führt eine frühere Serie namens Red Fort fort.

Alle Serien werden in Nicaragua von Hand gefertigt; das Haus nennt weder die Fabrik, die sie dreht, noch die Stadt, in der sie sich befindet. Im September 2026 ist Casa Culinaria bei Paul-Bugge.com und Cigarworld.de erhältlich.',
        '[{"name":"Connecticut","color":"#C9A96E","force":"Mild","wrapper":"Connecticut (USA)","vitolas":[],"story":"Herz aus nicaraguanischen Tabaken unter amerikanischem Deckblatt, Nachfolgerin einer früheren Serie Orange, so das Haus."},{"name":"Jalapa","color":"#8B5A2B","force":"Medium","wrapper":"Nicaragua","vitolas":[],"story":"Tabak ausschließlich aus der nicaraguanischen Region Jalapa, die der Serie ihren Namen gibt, so das Haus."},{"name":"Esteli","color":"#4A3728","force":"Medium-Full","wrapper":"Nicaragua","vitolas":[],"story":"Öliges, dunkles Deckblatt, Tabake aus der Region Esteli, in der Nachfolge einer früheren Serie Red Fort, so das Haus."}]',
        'Casa Culinaria是雪茄商Paul Bugge旗下的一个品牌，Paul Bugge来自黑森林地区的Villingen-Schwenningen；该商行未说明其创立年份。据Cigarworld.de介绍，其各系列最初以颜色命名；截至2026年9月，目录中共有三个系列。据商行介绍，Connecticut力度温和，外覆一层金黄色的美国茄衣，内含尼加拉瓜烟叶为芯，它承接了此前名为Orange的系列。Jalapa力度适中，其名称来自尼加拉瓜的一个地区，该地区提供了其大部分烟叶，茄衣也不例外。Esteli力度浓郁，茄衣油亮乌黑，承接了此前名为Red Fort的系列。

所有系列均在尼加拉瓜手工制作；该商行未透露卷制这些系列的工厂名称，也未透露其所在城市。截至2026年9月，Casa Culinaria在Paul-Bugge.com与Cigarworld.de有售。',
        '[{"name":"Connecticut","color":"#C9A96E","force":"Mild","wrapper":"Connecticut（美国）","vitolas":[],"story":"尼加拉瓜烟叶为芯，外覆美国茄衣，承接此前的Orange系列，商行如是说。"},{"name":"Jalapa","color":"#8B5A2B","force":"Medium","wrapper":"尼加拉瓜","vitolas":[],"story":"烟叶完全产自尼加拉瓜的Jalapa地区，该系列即以此地为名，商行如是说。"},{"name":"Esteli","color":"#4A3728","force":"Medium-Full","wrapper":"尼加拉瓜","vitolas":[],"story":"茄衣油亮乌黑，烟叶产自Esteli地区，是此前Red Fort系列的延续，商行如是说。"}]',
        'Casa Culinaria علامة تابعة لـPaul Bugge، تاجر سيجار من Villingen-Schwenningen في الغابة السوداء؛ ولا تحدد الدار تاريخ تأسيسها. وكانت سلاسلها تحمل في الأصل أسماء ألوان، بحسب Cigarworld.de؛ وحتى سبتمبر 2026، يضم الكتالوج ثلاث سلاسل. أما Connecticut، وهو خفيف القوة بحسب الدار، فيحمل غلافًا أمريكيًا ذهبي اللون فوق قلب من تبغ نيكاراغوا؛ وقد خلف سلسلة سابقة تحمل اسم Orange. أما Jalapa، فمتوسط القوة، ويأخذ اسمه من منطقة في نيكاراغوا يأتي منها معظم تبغه، بما في ذلك الغلاف. أما Esteli، فشديد القوة، بغلاف زيتي داكن، ويواصل مسيرة سلسلة سابقة تحمل اسم Red Fort.

تُصنع جميع السلاسل يدويًا في نيكاراغوا؛ ولا تكشف الدار عن اسم المصنع الذي يلفّها، ولا عن المدينة التي يقع فيها. وحتى سبتمبر 2026، Casa Culinaria معروضة للبيع لدى Paul-Bugge.com وCigarworld.de.',
        '[{"name":"Connecticut","color":"#C9A96E","force":"Mild","wrapper":"Connecticut (الولايات المتحدة)","vitolas":[],"story":"قلب من تبغ نيكاراغوا تحت غلاف أمريكي، خلَفًا لسلسلة Orange السابقة، بحسب الدار."},{"name":"Jalapa","color":"#8B5A2B","force":"Medium","wrapper":"نيكاراغوا","vitolas":[],"story":"تبغ نيكاراغوي بالكامل من منطقة Jalapa، التي تحمل السلسلة اسمها، بحسب الدار."},{"name":"Esteli","color":"#4A3728","force":"Medium-Full","wrapper":"نيكاراغوا","vitolas":[],"story":"غلاف زيتي داكن، من تبغ منطقة Esteli، استمرارًا لسلسلة Red Fort السابقة، بحسب الدار."}]')
ON DUPLICATE KEY UPDATE `country_id` = VALUES(`country_id`), `founded` = VALUES(`founded`), `factory` = VALUES(`factory`), `source` = VALUES(`source`), `mentions` = VALUES(`mentions`), `history` = VALUES(`history`), `gamme` = VALUES(`gamme`), `history_en` = VALUES(`history_en`), `gamme_en` = VALUES(`gamme_en`), `history_es` = VALUES(`history_es`), `gamme_es` = VALUES(`gamme_es`), `history_de` = VALUES(`history_de`), `gamme_de` = VALUES(`gamme_de`), `history_zh` = VALUES(`history_zh`), `gamme_zh` = VALUES(`gamme_zh`), `history_ar` = VALUES(`history_ar`), `gamme_ar` = VALUES(`gamme_ar`);

-- ── Casagranda ──
INSERT INTO `brands` (`name`, `country_id`, `founded`, `factory`, `source`, `mentions`, `history`, `gamme`, `history_en`, `gamme_en`, `history_es`, `gamme_es`, `history_de`, `gamme_de`, `history_zh`, `gamme_zh`, `history_ar`, `gamme_ar`)
VALUES ('Casagranda',
        'nicaragua',
        '2013 — Werner Casagranda, Esslingen (Allemagne)',
        'Nicaragua — la maison ne nomme pas sa fabrique',
        'casagranda-cigars.de « About CC » (en allemand ; consulté le 24 septembre 2026 : Werner Casagranda, société fondée en 2013 à Esslingen am Neckar, importateur de cigares boutique — portefeuille Horacio, Vegas de Santiago, Skull77, Tabacos de Costa Rica —, propose aussi des compositions de marque privée ; aucune fabrique n''est nommée pour une ligne propre) ; cigarworld.de « Casagranda: Zigarren kaufen » (consulté le 24 septembre 2026 : ligne Limitada — Gordo, Salomon, Torpedo, Torpedo Boxpressed — et ligne Overrun — H-2000 Robusto, Nr. 4 Robusto, Nr. 5 Petit Robusto —, toutes façonnées entièrement à la main, wrapper/sous-cape/tripe du Nicaragua ; fabrique non nommée) ; halfwheel « Hiram & Solomon Cigars Adds German Distribution » (consulté le 23 septembre 2026 : Casagranda Cigars GmbH ex-distributeur allemand de Hiram & Solomon, remplacé ensuite par Kohlhase & Kopp) ; casagranda-cigars.de « Vegas de Santiago » (en allemand ; consulté le 24 septembre 2026 : présente Vegas de Santiago, marque du Costa Rica, comme distribuée et non roulée par Casagranda, distincte de sa ligne maison)',
        NULL,
        'Casagranda Cigars GmbH naît en 2013 à Esslingen am Neckar, près de Stuttgart, quand Werner Casagranda se lance dans l''importation de cigares de boutique en Allemagne. Il distribue en exclusivité des marques tierces, dont Horacio et Vegas de Santiago, roulée au Costa Rica par Tabacos de Costa Rica S.A. ; il a aussi représenté un temps la marque américaine Hiram & Solomon en Allemagne, avant qu''elle ne passe chez Kohlhase & Kopp.

Sous son propre nom, la maison vend une ligne qui lui est propre, en deux séries : Limitada (Gordo, Salomon, Torpedo, Torpedo Boxpressed) et Overrun (H-2000 Robusto, Nr. 4, Nr. 5 Petit Robusto), toutes façonnées entièrement à la main, en Nicaragua puro — cape, sous-cape et tripe du pays, dit Cigarworld.de. La maison ne nomme pas la fabrique qui les roule, ni la ville où elle se trouve. En septembre 2026, la ligne est en vente chez Cigarworld.de.',
        '[{"name":"Limitada","color":"#A0522D","force":null,"wrapper":"Nicaragua","vitolas":[],"story":"Wrapper, sous-cape et tripe tous du Nicaragua, en Gordo, Salomon, Torpedo et Torpedo Boxpressed, dit le détaillant qui la vend."},{"name":"Overrun","color":"#A0522D","force":null,"wrapper":"Nicaragua","vitolas":[],"story":"Même origine nicaraguayenne, en formats H-2000 Robusto, Nr. 4 et Nr. 5 Petit Robusto."}]',
        'Casagranda Cigars GmbH was born in 2013 in Esslingen am Neckar, near Stuttgart, when Werner Casagranda launched into importing boutique cigars in Germany. He exclusively distributes third-party brands, including Horacio and Vegas de Santiago, rolled in Costa Rica by Tabacos de Costa Rica S.A.; he also represented the American brand Hiram & Solomon in Germany for a time, before it moved to Kohlhase & Kopp.

Under its own name, the house sells a line of its own, in two series: Limitada (Gordo, Salomon, Torpedo, Torpedo Boxpressed) and Overrun (H-2000 Robusto, Nr. 4, Nr. 5 Petit Robusto), all entirely hand-crafted, a Nicaragua puro — wrapper, binder and filler from the country, says Cigarworld.de. The house does not name the factory that rolls them, nor the town where it is located. As of September 2026, the line is on sale at Cigarworld.de.',
        '[{"name":"Limitada","color":"#A0522D","force":null,"wrapper":"Nicaragua","vitolas":[],"story":"Wrapper, binder and filler all from Nicaragua, in Gordo, Salomon, Torpedo and Torpedo Boxpressed, says the retailer that sells it."},{"name":"Overrun","color":"#A0522D","force":null,"wrapper":"Nicaragua","vitolas":[],"story":"Same Nicaraguan origin, in H-2000 Robusto, Nr. 4 and Nr. 5 Petit Robusto formats."}]',
        'Casagranda Cigars GmbH nace en 2013 en Esslingen am Neckar, cerca de Stuttgart, cuando Werner Casagranda se lanza a la importación de puros de boutique en Alemania. Distribuye en exclusiva marcas de terceros, entre ellas Horacio y Vegas de Santiago, torcida en Costa Rica por Tabacos de Costa Rica S.A.; también representó durante un tiempo la marca estadounidense Hiram & Solomon en Alemania, antes de que pasara a Kohlhase & Kopp.

Bajo su propio nombre, la casa vende una línea propia, en dos series: Limitada (Gordo, Salomon, Torpedo, Torpedo Boxpressed) y Overrun (H-2000 Robusto, Nr. 4, Nr. 5 Petit Robusto), todas elaboradas enteramente a mano, un Nicaragua puro — capa, capote y tripa del país, según Cigarworld.de. La casa no nombra la fábrica que las tuerce, ni la ciudad donde se encuentra. En septiembre de 2026, la línea está a la venta en Cigarworld.de.',
        '[{"name":"Limitada","color":"#A0522D","force":null,"wrapper":"Nicaragua","vitolas":[],"story":"Capa, capote y tripa, todos de Nicaragua, en Gordo, Salomon, Torpedo y Torpedo Boxpressed, según el minorista que la vende."},{"name":"Overrun","color":"#A0522D","force":null,"wrapper":"Nicaragua","vitolas":[],"story":"Mismo origen nicaragüense, en los formatos H-2000 Robusto, Nr. 4 y Nr. 5 Petit Robusto."}]',
        'Die Casagranda Cigars GmbH entsteht 2013 in Esslingen am Neckar, nahe Stuttgart, als Werner Casagranda in Deutschland in den Import von Boutique-Zigarren einsteigt. Er vertreibt exklusiv Fremdmarken, darunter Horacio und Vegas de Santiago, die in Costa Rica von Tabacos de Costa Rica S.A. gedreht wird; eine Zeit lang vertrat er auch die amerikanische Marke Hiram & Solomon in Deutschland, bevor sie zu Kohlhase & Kopp wechselte.

Unter eigenem Namen verkauft das Haus eine eigene Linie in zwei Serien: Limitada (Gordo, Salomon, Torpedo, Torpedo Boxpressed) und Overrun (H-2000 Robusto, Nr. 4, Nr. 5 Petit Robusto), alle vollständig von Hand gefertigt, ein Nicaragua puro — Deckblatt, Umblatt und Einlage aus dem Land, so Cigarworld.de. Das Haus nennt weder die Fabrik, die sie dreht, noch die Stadt, in der sie sich befindet. Im September 2026 ist die Linie bei Cigarworld.de erhältlich.',
        '[{"name":"Limitada","color":"#A0522D","force":null,"wrapper":"Nicaragua","vitolas":[],"story":"Deckblatt, Umblatt und Einlage allesamt aus Nicaragua, in Gordo, Salomon, Torpedo und Torpedo Boxpressed, so der Händler, der sie verkauft."},{"name":"Overrun","color":"#A0522D","force":null,"wrapper":"Nicaragua","vitolas":[],"story":"Gleiche nicaraguanische Herkunft, in den Formaten H-2000 Robusto, Nr. 4 und Nr. 5 Petit Robusto."}]',
        'Casagranda Cigars GmbH于2013年在斯图加特附近的内卡河畔埃斯林根创立，创始人Werner Casagranda当时开始在德国经营精品雪茄进口业务。他独家代理多个第三方品牌，其中包括Horacio与Vegas de Santiago——后者由Tabacos de Costa Rica S.A.在哥斯达黎加卷制；他还曾一度在德国代理美国品牌Hiram & Solomon，此后该品牌转投Kohlhase & Kopp。

该商行以自己的名字出售一条自有产品线，分为两个系列：Limitada（Gordo、Salomon、Torpedo、Torpedo Boxpressed）与Overrun（H-2000 Robusto、Nr. 4、Nr. 5 Petit Robusto），均为全手工制作的尼加拉瓜puro——茄衣、茄套与茄芯均产自该国，Cigarworld.de如是说。该商行未透露卷制这些系列的工厂名称，也未透露其所在城市。截至2026年9月，该产品线在Cigarworld.de有售。',
        '[{"name":"Limitada","color":"#A0522D","force":null,"wrapper":"尼加拉瓜","vitolas":[],"story":"茄衣、茄套与茄芯均产自尼加拉瓜，有Gordo、Salomon、Torpedo与Torpedo Boxpressed规格，销售该产品的零售商如是说。"},{"name":"Overrun","color":"#A0522D","force":null,"wrapper":"尼加拉瓜","vitolas":[],"story":"同样产自尼加拉瓜，有H-2000 Robusto、Nr. 4与Nr. 5 Petit Robusto等规格。"}]',
        'تأسست Casagranda Cigars GmbH عام 2013 في إسلينغن آم نكار، بالقرب من شتوتغارت، حين بدأ Werner Casagranda استيراد سيجار البوتيك إلى ألمانيا. وهو يوزّع حصريًا علامات تابعة لجهات أخرى، منها Horacio وVegas de Santiago التي تُلَفّ في كوستاريكا لدى Tabacos de Costa Rica S.A.؛ كما مثّل لفترة من الزمن العلامة الأمريكية Hiram & Solomon في ألمانيا، قبل أن تنتقل إلى Kohlhase & Kopp.

تبيع الدار، تحت اسمها الخاص، خطًّا خاصًّا بها، في سلسلتين: Limitada (Gordo وSalomon وTorpedo وTorpedo Boxpressed) وOverrun (H-2000 Robusto وNr. 4 وNr. 5 Petit Robusto)، جميعها مصنوعة يدويًا بالكامل، سيجار نيكاراغوا puro — غلاف وغلاف داخلي وحشوة من البلد نفسه، بحسب Cigarworld.de. ولا تكشف الدار عن اسم المصنع الذي يلفّها، ولا عن المدينة التي يقع فيها. وحتى سبتمبر 2026، الخط معروض للبيع لدى Cigarworld.de.',
        '[{"name":"Limitada","color":"#A0522D","force":null,"wrapper":"نيكاراغوا","vitolas":[],"story":"الغلاف والغلاف الداخلي والحشوة، كلها من نيكاراغوا، بمقاسات Gordo وSalomon وTorpedo وTorpedo Boxpressed، بحسب تاجر التجزئة الذي يبيعها."},{"name":"Overrun","color":"#A0522D","force":null,"wrapper":"نيكاراغوا","vitolas":[],"story":"المنشأ النيكاراغوي نفسه، بمقاسات H-2000 Robusto وNr. 4 وNr. 5 Petit Robusto."}]')
ON DUPLICATE KEY UPDATE `country_id` = VALUES(`country_id`), `founded` = VALUES(`founded`), `factory` = VALUES(`factory`), `source` = VALUES(`source`), `mentions` = VALUES(`mentions`), `history` = VALUES(`history`), `gamme` = VALUES(`gamme`), `history_en` = VALUES(`history_en`), `gamme_en` = VALUES(`gamme_en`), `history_es` = VALUES(`history_es`), `gamme_es` = VALUES(`gamme_es`), `history_de` = VALUES(`history_de`), `gamme_de` = VALUES(`gamme_de`), `history_zh` = VALUES(`history_zh`), `gamme_zh` = VALUES(`gamme_zh`), `history_ar` = VALUES(`history_ar`), `gamme_ar` = VALUES(`gamme_ar`);

-- ── Barrio Viejo ──
INSERT INTO `brands` (`name`, `country_id`, `founded`, `factory`, `source`, `mentions`, `history`, `gamme`, `history_en`, `gamme_en`, `history_es`, `gamme_es`, `history_de`, `gamme_de`, `history_zh`, `gamme_zh`, `history_ar`, `gamme_ar`)
VALUES ('Barrio Viejo',
        'honduras',
        '2019 — Thorsten Wolfertz, Solingen (Allemagne)',
        'Danlí, Honduras — la maison ne nomme pas sa fabrique',
        'smokersplanet.de « Wolfertz GmbH präsentiert Eigenmarke Barrio Viejo » (en allemand ; consulté 2026-09-24 : lancement le 29 avril 2019 par Thorsten Wolfertz, de Wolfertz GmbH, Solingen ; longfiller entièrement roulé à la main au Honduras, cape Nicaragua, sous-cape et tripe Honduras) ; cigarworld.de « Buy Barrio Viejo Cigars cigars » (consulté 2026-09-24 : six vitolas d''une seule ligne, du Half Corona au Churchill, force moyenne, notes épicées et rôties) ; starkezigarren.de « Barrio Viejo Zigarren » (consulté 2026-09-24 : confirme Danlí, Honduras, comme lieu où Wolfertz rencontre ses producteurs ; fabrique non nommée) ; trbusiness.com « VCF steps-up German market activity with Wörmann Cigars acquisition and Wolfertz takeover » (consulté 2026-09-24 : VCF reprend les activités de Wolfertz GmbH au 1er janvier 2023, Thorsten Wolfertz restant à la tête du commercial) ; halfwheel.com « Vandermarliere Cigar Family Acquiring Two German Cigar Companies » (2022 : VCF rachète Woermann Cigars GmbH et Wolfertz GmbH séparément en 2022 ; l''entité fusionnée VCF Germany prend effet le 1er janvier 2023).',
        NULL,
        'Barrio Viejo est une marque lancée le 29 avril 2019 par Thorsten Wolfertz, de la maison importatrice Wolfertz GmbH, à Solingen, en Allemagne, dit Smokersplanet.de. Le nom vient du vieux quartier du même nom, à Danlí, au Honduras, où Wolfertz rencontre ses producteurs. C''est là que se roule, entièrement à la main, ce longfiller en sous-cape et tripe honduriennes sous une cape nicaraguayenne sombre et huileuse ; cette cape le fait classer au Nicaragua par certains détaillants. La maison ne nomme pas la fabrique et s''en tient à Danlí.

Le 1er janvier 2023, les activités de Wolfertz GmbH passent à VCF (Vandermarliere Cigar Family), à la suite d''un accord conclu en 2022, dit halfwheel ; Thorsten Wolfertz reste à la tête du commercial, dit TRBusiness.

En septembre 2026, Cigarworld.de et StarkeZigarren.de tiennent Barrio Viejo au catalogue : une seule ligne en six vitolas, du Half Corona (3,5 x 44) au Churchill (7 x 52), de force moyenne selon Cigarworld.de.',
        '[{"name":"Barrio Viejo","color":"#6B4226","force":"Medium","wrapper":"Nicaragua (foncée, huileuse)","vitolas":[],"story":"Longfiller en six vitolas, du Half Corona (3,5 x 44) au Churchill (7 x 52), sur sous-cape et tripe honduriennes."}]',
        'Barrio Viejo is a brand launched on 29 April 2019 by Thorsten Wolfertz, of the importing house Wolfertz GmbH, in Solingen, Germany, says Smokersplanet.de. The name comes from the old quarter of the same name, in Danlí, Honduras, where Wolfertz meets his growers. It is there that this longfiller, with a Honduran binder and filler under a dark, oily Nicaraguan wrapper, is rolled entirely by hand; this wrapper leads some retailers to list it under Nicaragua. The house does not name the factory, giving only Danlí.

On 1 January 2023, the operations of Wolfertz GmbH passed to VCF (Vandermarliere Cigar Family), following an agreement reached in 2022, says halfwheel; Thorsten Wolfertz remains head of sales, says TRBusiness.

As of September 2026, Cigarworld.de and StarkeZigarren.de list Barrio Viejo in their catalogue: a single line in six vitolas, from the Half Corona (3.5 x 44) to the Churchill (7 x 52), medium-bodied according to Cigarworld.de.',
        '[{"name":"Barrio Viejo","color":"#6B4226","force":"Medium","wrapper":"Nicaragua (dark, oily)","vitolas":[],"story":"Longfiller in six vitolas, from the Half Corona (3.5 x 44) to the Churchill (7 x 52), on a Honduran binder and filler."}]',
        'Barrio Viejo es una marca lanzada el 29 de abril de 2019 por Thorsten Wolfertz, de la casa importadora Wolfertz GmbH, en Solingen (Alemania), según Smokersplanet.de. El nombre procede del casco antiguo del mismo nombre, en Danlí (Honduras), donde Wolfertz se reúne con sus productores. Allí se lía, enteramente a mano, este longfiller de capote y tripa hondureños bajo una capa nicaragüense oscura y aceitosa; esta capa lleva a algunos vendedores a clasificarlo como nicaragüense. La casa no revela la fábrica y se limita a mencionar Danlí.

El 1 de enero de 2023, las actividades de Wolfertz GmbH pasan a VCF (Vandermarliere Cigar Family), tras un acuerdo alcanzado en 2022, según halfwheel; Thorsten Wolfertz sigue al frente del área comercial, según TRBusiness.

En septiembre de 2026, Cigarworld.de y StarkeZigarren.de tienen a Barrio Viejo en catálogo: una sola línea en seis vitolas, desde el Half Corona (3,5 x 44) hasta el Churchill (7 x 52), de fuerza media según Cigarworld.de.',
        '[{"name":"Barrio Viejo","color":"#6B4226","force":"Medium","wrapper":"Nicaragua (oscura, aceitosa)","vitolas":[],"story":"Longfiller en seis vitolas, desde el Half Corona (3,5 x 44) hasta el Churchill (7 x 52), sobre capote y tripa hondureños."}]',
        'Barrio Viejo ist eine Marke, die am 29. April 2019 von Thorsten Wolfertz vom Importhaus Wolfertz GmbH in Solingen ins Leben gerufen wurde, so Smokersplanet.de. Der Name stammt vom gleichnamigen Altstadtviertel in Danlí, Honduras, wo Wolfertz seine Erzeuger trifft. Dort wird dieser Longfiller mit honduranischem Umblatt und honduranischer Einlage unter einem dunklen, öligen nicaraguanischen Deckblatt vollständig von Hand gedreht; dieses Deckblatt veranlasst manche Händler, ihn Nicaragua zuzuordnen. Das Haus nennt die Fabrik nicht und beschränkt sich auf die Angabe Danlí.

Am 1. Januar 2023 gehen die Geschäfte der Wolfertz GmbH infolge einer 2022 geschlossenen Vereinbarung auf VCF (Vandermarliere Cigar Family) über, so halfwheel; Thorsten Wolfertz bleibt an der Spitze des Vertriebs, so TRBusiness.

Im September 2026 führen Cigarworld.de und StarkeZigarren.de Barrio Viejo im Sortiment: eine einzige Linie in sechs Formaten, vom Half Corona (3,5 x 44) bis zum Churchill (7 x 52), laut Cigarworld.de mittelkräftig.',
        '[{"name":"Barrio Viejo","color":"#6B4226","force":"Medium","wrapper":"Nicaragua (dunkel, ölig)","vitolas":[],"story":"Longfiller in sechs Formaten, vom Half Corona (3,5 x 44) bis zum Churchill (7 x 52), mit honduranischem Umblatt und honduranischer Einlage."}]',
        'Barrio Viejo是Thorsten Wolfertz于2019年4月29日创立的品牌，其进口商Wolfertz GmbH总部位于德国索林根，据Smokersplanet.de报道。品牌名称源自洪都拉斯丹利同名的老城区，Wolfertz在那里与烟叶种植者会面。这款longfiller正是在当地完全手工卷制而成，采用洪都拉斯包套叶与烟芯，外覆深色油亮的尼加拉瓜茄衣；正因这层茄衣，部分零售商将其归入尼加拉瓜雪茄之列。厂方未透露卷制工厂名称，只表示产地为丹利。

2023年1月1日，根据2022年达成的协议，Wolfertz GmbH的业务转由VCF（Vandermarliere Cigar Family）接手，据halfwheel报道；Thorsten Wolfertz继续执掌销售业务，据TRBusiness报道。

截至2026年9月，Cigarworld.de与StarkeZigarren.de的产品目录中均列有Barrio Viejo：单一系列，六种规格，从Half Corona（3.5 x 44）到Churchill（7 x 52），据Cigarworld.de称，力度中等。',
        '[{"name":"Barrio Viejo","color":"#6B4226","force":"Medium","wrapper":"尼加拉瓜（深色，油亮）","vitolas":[],"story":"Longfiller，六种规格，从Half Corona（3.5 x 44）到Churchill（7 x 52），配以洪都拉斯包套叶与烟芯。"}]',
        'علامة Barrio Viejo أطلقها Thorsten Wolfertz في 29 أبريل 2019، وهو من دار الاستيراد Wolfertz GmbH في مدينة زولينجن بألمانيا، بحسب Smokersplanet.de. يعود الاسم إلى الحي القديم الذي يحمل الاسم نفسه في مدينة دانلي بهندوراس، حيث يلتقي Wolfertz بمزارعيه. هناك يُلَفّ هذا السيجار من نوع longfiller يدويًا بالكامل، برباط هندوراسي وحشوة هندوراسية تحت غلاف نيكاراغوي داكن ولامع بالزيت؛ وهذا الغلاف يدفع بعض تجار التجزئة إلى تصنيفه ضمن سيجار نيكاراغوا. لا تكشف الدار عن اسم المصنع وتكتفي بذكر دانلي.

في 1 يناير 2023، انتقلت أنشطة Wolfertz GmbH إلى VCF (Vandermarliere Cigar Family) إثر اتفاق أُبرم عام 2022، بحسب halfwheel؛ ويبقى Thorsten Wolfertz على رأس القسم التجاري، بحسب TRBusiness.

حتى سبتمبر 2026، تُدرج Cigarworld.de وStarkeZigarren.de علامة Barrio Viejo في كتالوجهما: خط واحد بست مقاسات، من Half Corona (3.5 x 44) إلى Churchill (7 x 52)، متوسط القوة بحسب Cigarworld.de.',
        '[{"name":"Barrio Viejo","color":"#6B4226","force":"Medium","wrapper":"نيكاراغوا (داكن ولامع بالزيت)","vitolas":[],"story":"سيجار من نوع longfiller بست مقاسات، من Half Corona (3.5 x 44) إلى Churchill (7 x 52)، برباط هندوراسي وحشوة هندوراسية."}]')
