-- ── Atatürk ──
INSERT INTO `brands` (`name`, `country_id`, `founded`, `factory`, `source`, `mentions`, `history`, `gamme`, `history_en`, `gamme_en`, `history_es`, `gamme_es`, `history_de`, `gamme_de`, `history_zh`, `gamme_zh`, `history_ar`, `gamme_ar`)
VALUES ('Atatürk',
        'indonesia',
        'Non précisée — Jimmy Sartika, Indonésie',
        'Indonésie — la maison ne nomme pas sa fabrique',
        'etwasgenuss.de « Atatürk Robusto – Von der Glasfaser zur perfekten Glut » (en allemand ; consulté 2026-09-24 : Atatürk 1923 créé par l''entrepreneur indonésien Jimmy Sartika, surnommé Cigar Man, venu des télécommunications, en hommage à Mustafa Kemal Atatürk) ; cigarworld.de « Atatürk Zigarren » (en allemand ; consulté 2026-09-24 : cape Javano d''Indonésie, sous-cape Besuki Na-Oogst, tripe entièrement indonésienne, un seul vitola Robusto, fiche créée sur le site le 29 mai 2024) ; noblego.de « Atatürk Robusto » (consulté 2026-09-24 : confirme l''origine indonésienne et le roulage à la main, sans nommer de fabrique) ; starkezigarren.de « Atatürk Robusto » (consulté 2026-09-24 : vente courante en Allemagne).',
        NULL,
        'Atatürk 1923 est la marque de l''entrepreneur indonésien Jimmy Sartika, surnommé Cigar Man, venu de la fibre optique et des télécommunications, dit Etwasgenuss.de. Le nom rend hommage à Mustafa Kemal Atatürk et à l''année 1923, celle où il proclame la République turque ; la maison ne date pas sa création.

Le cigare est un puro roulé à la main en Indonésie : cape Javano, sous-cape Besuki Na-Oogst, venue de la région de Besuki, à Java-Est, et tripe entièrement indonésienne, dit Cigarworld.de. La maison ne nomme pas la fabrique qui le roule.

En septembre 2026, une seule vitola est au catalogue, le Robusto, en vente chez Cigarworld.de depuis le 29 mai 2024, ainsi que chez Noblego.de et StarkeZigarren.de ; Cigarworld.de le dit de force douce à moyenne.',
        '[{"name":"Atatürk 1923","color":"#A0522D","force":"Mild-Medium","wrapper":"Javano (Indonésie)","vitolas":[],"story":"Puro intégralement indonésien, sous-cape Besuki Na-Oogst, en hommage à Mustafa Kemal Atatürk."}]',
        'Atatürk 1923 is the brand of the Indonesian entrepreneur Jimmy Sartika, nicknamed Cigar Man, who came from fibre optics and telecommunications, says Etwasgenuss.de. The name pays tribute to Mustafa Kemal Atatürk and to the year 1923, when he proclaimed the Turkish Republic; the house does not date its founding.

The cigar is a puro rolled by hand in Indonesia: a Javano wrapper, a Besuki Na-Oogst binder from the Besuki region, in East Java, and an entirely Indonesian filler, says Cigarworld.de. The house does not name the factory that rolls it.

As of September 2026, a single vitola is in the catalogue, the Robusto, on sale at Cigarworld.de since 29 May 2024, as well as at Noblego.de and StarkeZigarren.de; Cigarworld.de rates it mild to medium in strength.',
        '[{"name":"Atatürk 1923","color":"#A0522D","force":"Mild-Medium","wrapper":"Javano (Indonesia)","vitolas":[],"story":"Puro entirely from Indonesia, with a Besuki Na-Oogst binder, in tribute to Mustafa Kemal Atatürk."}]',
        'Atatürk 1923 es la marca del empresario indonesio Jimmy Sartika, apodado Cigar Man, procedente de la fibra óptica y las telecomunicaciones, según Etwasgenuss.de. El nombre rinde homenaje a Mustafa Kemal Atatürk y al año 1923, en el que proclamó la República turca; la casa no data su creación.

El cigarro es un puro liado a mano en Indonesia: capa Javano, capote Besuki Na-Oogst, procedente de la región de Besuki, en Java Oriental, y tripa enteramente indonesia, según Cigarworld.de. La casa no nombra la fábrica que lo lía.

En septiembre de 2026, una sola vitola figura en el catálogo, el Robusto, a la venta en Cigarworld.de desde el 29 de mayo de 2024, así como en Noblego.de y StarkeZigarren.de; Cigarworld.de lo califica de fuerza suave a media.',
        '[{"name":"Atatürk 1923","color":"#A0522D","force":"Mild-Medium","wrapper":"Javano (Indonesia)","vitolas":[],"story":"Puro íntegramente indonesio, con capote Besuki Na-Oogst, en homenaje a Mustafa Kemal Atatürk."}]',
        'Atatürk 1923 ist die Marke des indonesischen Unternehmers Jimmy Sartika, genannt Cigar Man, der aus der Glasfaser- und Telekommunikationsbranche kommt, so Etwasgenuss.de. Der Name ehrt Mustafa Kemal Atatürk und das Jahr 1923, in dem er die Republik Türkei ausrief; das Haus datiert seine Gründung nicht.

Die Zigarre ist ein in Indonesien von Hand gedrehter Puro: Deckblatt Javano, Umblatt Besuki Na-Oogst aus der Region Besuki in Ost-Java, und vollständig indonesische Einlage, so Cigarworld.de. Das Haus nennt die Fabrik, die sie dreht, nicht.

Im September 2026 führt das Sortiment eine einzige Vitola, den Robusto, der seit dem 29. Mai 2024 bei Cigarworld.de sowie bei Noblego.de und StarkeZigarren.de erhältlich ist; Cigarworld.de stuft ihn als mild bis mittelkräftig ein.',
        '[{"name":"Atatürk 1923","color":"#A0522D","force":"Mild-Medium","wrapper":"Javano (Indonesien)","vitolas":[],"story":"Puro vollständig aus Indonesien, mit Umblatt Besuki Na-Oogst, zu Ehren von Mustafa Kemal Atatürk."}]',
        'Atatürk 1923是印度尼西亚企业家Jimmy Sartika的品牌，此人绰号Cigar Man，出身光纤与电信行业，据Etwasgenuss.de报道。品牌名称向穆斯塔法·凯末尔·阿塔图尔克及其宣告成立土耳其共和国的1923年致敬；厂方未说明品牌创立的具体年份。

这款雪茄是在印度尼西亚手工卷制的puro：茄衣为Javano，包套叶为Besuki Na-Oogst，产自东爪哇的贝苏基地区，烟芯则完全产自印度尼西亚，据Cigarworld.de报道。厂方未透露卷制工厂的名称。

截至2026年9月，产品目录中仅有一种规格Robusto，自2024年5月29日起在Cigarworld.de发售，同时也在Noblego.de与StarkeZigarren.de有售；Cigarworld.de将其力度评为温和至中等。',
        '[{"name":"Atatürk 1923","color":"#A0522D","force":"Mild-Medium","wrapper":"Javano（印度尼西亚）","vitolas":[],"story":"完全产自印度尼西亚的puro，包套叶为Besuki Na-Oogst，向穆斯塔法·凯末尔·阿塔图尔克致敬。"}]',
        'علامة Atatürk 1923 هي علامة رجل الأعمال الإندونيسي Jimmy Sartika، الملقب Cigar Man، القادم من قطاعي الألياف الضوئية والاتصالات، بحسب Etwasgenuss.de. يكرّم الاسم مصطفى كمال أتاتورك وعام 1923، وهو العام الذي أعلن فيه الجمهورية التركية؛ ولا تحدّد الدار تاريخ تأسيسها.

السيجار عبارة عن puro مُلفوف يدويًا في إندونيسيا: غلاف من نوع Javano، ورباط من نوع Besuki Na-Oogst قادم من منطقة بيسوكي في جاوة الشرقية، وحشوة إندونيسية بالكامل، بحسب Cigarworld.de. ولا تكشف الدار عن اسم المصنع الذي يلفّه.

حتى سبتمبر 2026، يضمّ الكتالوج مقاسًا واحدًا فقط، هو Robusto، المعروض للبيع لدى Cigarworld.de منذ 29 مايو 2024، وكذلك لدى Noblego.de وStarkeZigarren.de؛ وتصفه Cigarworld.de بأنه خفيف إلى متوسط القوة.',
        '[{"name":"Atatürk 1923","color":"#A0522D","force":"Mild-Medium","wrapper":"Javano (إندونيسيا)","vitolas":[],"story":"puro إندونيسي بالكامل، برباط Besuki Na-Oogst، تكريمًا لمصطفى كمال أتاتورك."}]')
ON DUPLICATE KEY UPDATE `country_id` = VALUES(`country_id`), `founded` = VALUES(`founded`), `factory` = VALUES(`factory`), `source` = VALUES(`source`), `mentions` = VALUES(`mentions`), `history` = VALUES(`history`), `gamme` = VALUES(`gamme`), `history_en` = VALUES(`history_en`), `gamme_en` = VALUES(`gamme_en`), `history_es` = VALUES(`history_es`), `gamme_es` = VALUES(`gamme_es`), `history_de` = VALUES(`history_de`), `gamme_de` = VALUES(`gamme_de`), `history_zh` = VALUES(`history_zh`), `gamme_zh` = VALUES(`gamme_zh`), `history_ar` = VALUES(`history_ar`), `gamme_ar` = VALUES(`gamme_ar`);

-- ── Chone ──
INSERT INTO `brands` (`name`, `country_id`, `founded`, `factory`, `source`, `mentions`, `history`, `gamme`, `history_en`, `gamme_en`, `history_es`, `gamme_es`, `history_de`, `gamme_de`, `history_zh`, `gamme_zh`, `history_ar`, `gamme_ar`)
VALUES ('Chone',
        'indonesia',
        '2016 — Annis Arahma, dite Icha (Indonésie)',
        'Jember, Indonésie — la maison ne nomme pas sa fabrique',
        'starkezigarren.de « StarkeZigarren interviewt Annis Arahma von Chone Cigars » (consulté 2026-09-24 : entretien avec Annis Arahma, dite Icha, qui découvre le cigare à Jakarta en 2008 et crée Chone après une expérience décevante avec un cigare indonésien en 2016 ; roulage à Jember, auprès de quatre manufactures aux spécialités différentes, aucune n''étant nommée comme fabrique attitrée) ; smokersplanet.de « Chone – Luxuscigarren aus Indonesien » (en allemand ; consulté 2026-09-24 : situe l''idée fondatrice lors d''un voyage à Bali en 2016) ; cigarworld.de « Chone » (consulté 2026-09-24 : catalogue actuel en quatre lignes — Eudaemonia, Master''s Select, Maduro 8, Java Treasure —, longfiller entièrement roulé à la main, fiche créée sur le site le 15 mai 2024).',
        NULL,
        'Annis Arahma, dite Icha dans le milieu indonésien du cigare, découvre le cigare à Jakarta en 2008. En 2016, lors d''un voyage à Bali, dit Smokersplanet.de, un cigare indonésien décevant la décide à créer sa propre marque : l''Indonésie, grand pays producteur de tabac, mérite mieux, dit-elle à StarkeZigarren.de. Chone Cigars naît ainsi, sans plan d''affaires arrêté.

Le roulage se fait dans la région de Jember, à Java-Est. Annis Arahma dit y travailler avec quatre manufactures aux spécialités différentes — certaines ne roulent que du tabac local, d''autres travaillent une seule variété par des fermentations élaborées —, sans en nommer aucune comme fabrique de la marque.

En septembre 2026, Cigarworld.de tient quatre lignes au catalogue, toutes en longfiller roulé entièrement à la main : Master''s Select, lancée en 2019, que sa fondatrice dit sa préférée ; Eudaemonia ; Maduro 8 ; et Java Treasure, série limitée de vieux tabacs.',
        '[{"name":"Master''s Select","color":"#8B5A2B","force":null,"wrapper":"Non divulguée","vitolas":[],"story":"Lancée en 2019, dite par Annis Arahma sa ligne préférée."},{"name":"Eudaemonia","color":"#6B4226","force":null,"wrapper":"Non divulguée","vitolas":[],"story":"Conçue, dit Annis Arahma, pour procurer du bien-être aux amateurs."},{"name":"Maduro 8","color":"#4A3728","force":null,"wrapper":"Maduro","vitolas":[],"story":"Ligne à cape maduro."},{"name":"Java Treasure","color":"#4A3728","force":null,"wrapper":"Non divulguée","vitolas":[],"story":"Série limitée composée de vieux tabacs, dit cigarworld.de."}]',
        'Annis Arahma, known as Icha in Indonesia''s cigar circles, discovers cigars in Jakarta in 2008. In 2016, during a trip to Bali, says Smokersplanet.de, a disappointing Indonesian cigar leads her to create her own brand: Indonesia, a major tobacco-growing country, deserves better, she tells StarkeZigarren.de. Chone Cigars is thus born, without a fixed business plan.

Rolling takes place in the Jember region, in East Java. Annis Arahma says she works there with four factories, each with different specialities — some roll only local tobacco, others work a single variety through elaborate fermentations — without naming any of them as the brand''s factory.

As of September 2026, Cigarworld.de lists four lines in its catalogue, all longfillers rolled entirely by hand: Master''s Select, launched in 2019, which its founder calls her favourite; Eudaemonia; Maduro 8; and Java Treasure, a limited series of aged tobaccos.',
        '[{"name":"Master''s Select","color":"#8B5A2B","force":null,"wrapper":"Undisclosed","vitolas":[],"story":"Launched in 2019, said by Annis Arahma to be her favourite line."},{"name":"Eudaemonia","color":"#6B4226","force":null,"wrapper":"Undisclosed","vitolas":[],"story":"Designed, says Annis Arahma, to bring well-being to enthusiasts."},{"name":"Maduro 8","color":"#4A3728","force":null,"wrapper":"Maduro","vitolas":[],"story":"Line with a maduro wrapper."},{"name":"Java Treasure","color":"#4A3728","force":null,"wrapper":"Undisclosed","vitolas":[],"story":"Limited series made up of aged tobaccos, says Cigarworld.de."}]',
        'Annis Arahma, conocida como Icha en el mundillo indonesio del cigarro, descubre el cigarro en Yakarta en 2008. En 2016, durante un viaje a Bali, según Smokersplanet.de, un cigarro indonesio decepcionante la lleva a crear su propia marca: Indonesia, gran país productor de tabaco, merece algo mejor, declara a StarkeZigarren.de. Así nace Chone Cigars, sin un plan de negocio definido.

El liado se realiza en la región de Jember, en Java Oriental. Annis Arahma dice trabajar allí con cuatro fábricas de especialidades distintas —unas lían solo tabaco local, otras trabajan una sola variedad mediante fermentaciones elaboradas—, sin nombrar a ninguna como fábrica de la marca.

En septiembre de 2026, Cigarworld.de tiene cuatro líneas en catálogo, todas en longfiller, liadas enteramente a mano: Master''s Select, lanzada en 2019, que su fundadora dice que es su preferida; Eudaemonia; Maduro 8; y Java Treasure, serie limitada de tabacos añejos.',
        '[{"name":"Master''s Select","color":"#8B5A2B","force":null,"wrapper":"No divulgada","vitolas":[],"story":"Lanzada en 2019, calificada por Annis Arahma como su línea preferida."},{"name":"Eudaemonia","color":"#6B4226","force":null,"wrapper":"No divulgada","vitolas":[],"story":"Concebida, según Annis Arahma, para proporcionar bienestar a los aficionados."},{"name":"Maduro 8","color":"#4A3728","force":null,"wrapper":"Maduro","vitolas":[],"story":"Línea con capa maduro."},{"name":"Java Treasure","color":"#4A3728","force":null,"wrapper":"No divulgada","vitolas":[],"story":"Serie limitada compuesta de tabacos añejos, según Cigarworld.de."}]',
        'Annis Arahma, in der indonesischen Zigarrenszene Icha genannt, entdeckt die Zigarre 2008 in Jakarta. 2016, während einer Reise nach Bali, so Smokersplanet.de, bringt sie eine enttäuschende indonesische Zigarre dazu, eine eigene Marke zu gründen: Indonesien, ein bedeutendes Tabakanbauland, verdiene Besseres, sagt sie StarkeZigarren.de. So entsteht Chone Cigars, ohne festgelegten Geschäftsplan.

Gedreht wird in der Region Jember, in Ost-Java. Annis Arahma sagt, dort mit vier Fabriken unterschiedlicher Spezialisierung zusammenzuarbeiten — manche drehen nur lokalen Tabak, andere bearbeiten eine einzige Sorte mit aufwendigen Fermentationen —, ohne eine von ihnen als Fabrik der Marke zu nennen.

Im September 2026 führt Cigarworld.de vier Linien im Sortiment, alle als vollständig von Hand gedrehte Longfiller: Master''s Select, 2019 lanciert und von der Gründerin als ihre Lieblingslinie bezeichnet; Eudaemonia; Maduro 8; sowie Java Treasure, eine limitierte Serie aus altem Tabak.',
        '[{"name":"Master''s Select","color":"#8B5A2B","force":null,"wrapper":"Nicht angegeben","vitolas":[],"story":"2019 lanciert, von Annis Arahma als ihre Lieblingslinie bezeichnet."},{"name":"Eudaemonia","color":"#6B4226","force":null,"wrapper":"Nicht angegeben","vitolas":[],"story":"Entwickelt, so Annis Arahma, um Liebhabern Wohlbefinden zu schenken."},{"name":"Maduro 8","color":"#4A3728","force":null,"wrapper":"Maduro","vitolas":[],"story":"Linie mit Maduro-Deckblatt."},{"name":"Java Treasure","color":"#4A3728","force":null,"wrapper":"Nicht angegeben","vitolas":[],"story":"Limitierte Serie aus altem Tabak, so Cigarworld.de."}]',
        'Annis Arahma在印度尼西亚雪茄圈内被称为Icha，2008年在雅加达接触到雪茄。据Smokersplanet.de报道，2016年，在一次巴厘岛之行中，一支令人失望的印度尼西亚雪茄促使她决心创立自己的品牌：她对StarkeZigarren.de说，印度尼西亚身为产烟大国，理应做得更好。Chone Cigars由此诞生，当时并无明确的商业计划。

卷制工作在东爪哇的杰姆贝尔地区进行。Annis Arahma说，她在那里与四家专长各异的工厂合作——有的只卷制本地烟叶，有的则通过精细发酵专注于单一品种——但未指明其中任何一家为品牌的卷制工厂。

截至2026年9月，Cigarworld.de的产品目录中列有四条系列，均为完全手工卷制的longfiller：Master''s Select，2019年推出，创始人称其为自己偏爱的系列；Eudaemonia；Maduro 8；以及限量系列Java Treasure，选用陈年烟叶。',
        '[{"name":"Master''s Select","color":"#8B5A2B","force":null,"wrapper":"未公开","vitolas":[],"story":"2019年推出，Annis Arahma称之为自己偏爱的系列。"},{"name":"Eudaemonia","color":"#6B4226","force":null,"wrapper":"未公开","vitolas":[],"story":"据Annis Arahma说，此系列旨在为爱好者带来身心愉悦。"},{"name":"Maduro 8","color":"#4A3728","force":null,"wrapper":"Maduro","vitolas":[],"story":"茄衣为maduro的系列。"},{"name":"Java Treasure","color":"#4A3728","force":null,"wrapper":"未公开","vitolas":[],"story":"据Cigarworld.de介绍，这是一款以陈年烟叶制成的限量系列。"}]',
        'تكتشف Annis Arahma، المعروفة باسم Icha في أوساط السيجار الإندونيسية، عالم السيجار في جاكرتا عام 2008. وفي عام 2016، خلال رحلة إلى بالي، بحسب Smokersplanet.de، دفعتها تجربة سيجار إندونيسي مخيّب للآمال إلى إنشاء علامتها الخاصة: فإندونيسيا، بلد كبير منتج للتبغ، تستحق ما يليق بها، كما قالت لموقع StarkeZigarren.de. وهكذا وُلدت Chone Cigars، من دون خطة عمل محددة سلفًا.

تجري عملية اللف في منطقة جيمبر، بجاوة الشرقية. وتقول Annis Arahma إنها تعمل هناك مع أربعة مصانع بتخصصات مختلفة — بعضها لا يلف سوى التبغ المحلي، وبعضها الآخر يعمل على صنف واحد عبر تخمير مُعقَّد — من دون أن تسمّي أيًّا منها بوصفه مصنع العلامة.

حتى سبتمبر 2026، يضمّ كتالوج Cigarworld.de أربعة خطوط، جميعها من نوع longfiller مُلفوف يدويًا بالكامل: Master''s Select، الذي أُطلق عام 2019 وتصفه مؤسِّسته بأنه المفضّل لديها؛ وEudaemonia؛ وMaduro 8؛ وJava Treasure، وهي سلسلة محدودة من تبغ معتَّق.',
        '[{"name":"Master''s Select","color":"#8B5A2B","force":null,"wrapper":"غير معلن","vitolas":[],"story":"أُطلقت عام 2019، وتصفها Annis Arahma بأنها خطها المفضّل لديها."},{"name":"Eudaemonia","color":"#6B4226","force":null,"wrapper":"غير معلن","vitolas":[],"story":"صُمِّم، بحسب Annis Arahma، لمنح الهواة شعورًا بالراحة والرفاهية."},{"name":"Maduro 8","color":"#4A3728","force":null,"wrapper":"Maduro","vitolas":[],"story":"خط بغلاف من نوع maduro."},{"name":"Java Treasure","color":"#4A3728","force":null,"wrapper":"غير معلن","vitolas":[],"story":"سلسلة محدودة مكوَّنة من تبغ معتَّق، بحسب Cigarworld.de."}]')
ON DUPLICATE KEY UPDATE `country_id` = VALUES(`country_id`), `founded` = VALUES(`founded`), `factory` = VALUES(`factory`), `source` = VALUES(`source`), `mentions` = VALUES(`mentions`), `history` = VALUES(`history`), `gamme` = VALUES(`gamme`), `history_en` = VALUES(`history_en`), `gamme_en` = VALUES(`gamme_en`), `history_es` = VALUES(`history_es`), `gamme_es` = VALUES(`gamme_es`), `history_de` = VALUES(`history_de`), `gamme_de` = VALUES(`gamme_de`), `history_zh` = VALUES(`history_zh`), `gamme_zh` = VALUES(`gamme_zh`), `history_ar` = VALUES(`history_ar`), `gamme_ar` = VALUES(`gamme_ar`);

-- ── Chinchalero ──
INSERT INTO `brands` (`name`, `country_id`, `founded`, `factory`, `source`, `mentions`, `history`, `gamme`, `history_en`, `gamme_en`, `history_es`, `gamme_es`, `history_de`, `gamme_de`, `history_zh`, `gamme_zh`, `history_ar`, `gamme_ar`)
VALUES ('Chinchalero',
        'nicaragua',
        '2011 — John Atherton',
        'Nicaragua — la maison ne nomme pas sa fabrique',
        'cigarworld.de « Chinchalero » (consulté 2026-09-24 : fondée en 2011 par John Atherton, passé plusieurs années par la division internationale de General Cigar ; longfiller roulé à la main au Nicaragua ; catalogue en quatre lignes — Classic, Torcidos, Mezcla 40, Reserva de Oro discontinuée) ; kohlhase-soehne.com « Chinchalero » (consulté 2026-09-24 : confirme John Atherton comme fondateur, sans mention de fabrique) ; cgarsltd.co.uk « Buy Chinchalero cigars online » (consulté 2026-09-23 : fondée en 2011 par John Atherton, roulée à la main au Nicaragua, cape Ecuador Shade) ; thehouseofcigars.co.uk « Chinchalero Cigars » (consulté 2026-09-24 : confirme le Nicaragua et le roulage à la main, sans nommer de fabrique).',
        NULL,
        'Chinchalero est fondée en 2011 par John Atherton, passé plusieurs années par la division internationale de General Cigar, dit Cigarworld.de. Le nom renvoie aux chinchales, les petits ateliers où se roule traditionnellement le cigare.

Les cigares, des longfillers, se roulent entièrement à la main au Nicaragua ; la maison ne nomme pas la fabrique, ni la ville où elle se trouve.

En septembre 2026, le catalogue compte trois lignes, dit Cigarworld.de : Classic, dite plus douce, à bague bleue ; Torcidos, à double cape, Connecticut clair et Maduro sombre ; Mezcla 40, sous cape Connecticut d''Équateur, aux notes sucrées et épicées. Une quatrième ligne, Reserva de Oro, à bague rouge, n''y figure plus.',
        '[{"name":"Classic","color":"#8B5A2B","force":null,"wrapper":"Non divulguée","vitolas":[],"story":"À bague bleue, dite plus douce par Cigarworld.de."},{"name":"Torcidos","color":"#6B4226","force":null,"wrapper":"Connecticut / Maduro","vitolas":[],"story":"Double cape contrastée, Connecticut clair et Maduro sombre, dit cigarworld.de."},{"name":"Mezcla 40","color":"#C9A96E","force":null,"wrapper":"Connecticut équatorien","vitolas":[],"story":"Notes sucrées et épicées sous cape Connecticut équatorienne, dit cigarworld.de."}]',
        'Chinchalero is founded in 2011 by John Atherton, who spent several years with General Cigar''s international division, says Cigarworld.de. The name refers to the chinchales, the small workshops where cigars are traditionally rolled.

The cigars, longfillers, are rolled entirely by hand in Nicaragua; the house does not name the factory, nor the city where it is located.

As of September 2026, the catalogue comprises three lines, says Cigarworld.de: Classic, said to be milder, with a blue band; Torcidos, with a double wrapper, light Connecticut and dark Maduro; Mezcla 40, under an Ecuadorian Connecticut wrapper, with sweet and spicy notes. A fourth line, Reserva de Oro, with a red band, no longer appears there.',
        '[{"name":"Classic","color":"#8B5A2B","force":null,"wrapper":"Undisclosed","vitolas":[],"story":"With a blue band, said by Cigarworld.de to be milder."},{"name":"Torcidos","color":"#6B4226","force":null,"wrapper":"Connecticut / Maduro","vitolas":[],"story":"Contrasting double wrapper, light Connecticut and dark Maduro, says Cigarworld.de."},{"name":"Mezcla 40","color":"#C9A96E","force":null,"wrapper":"Ecuadorian Connecticut","vitolas":[],"story":"Sweet and spicy notes under an Ecuadorian Connecticut wrapper, says cigarworld.de."}]',
        'Chinchalero se funda en 2011 por John Atherton, quien pasó varios años en la división internacional de General Cigar, según Cigarworld.de. El nombre remite a los chinchales, los pequeños talleres donde tradicionalmente se lía el cigarro.

Los cigarros, longfillers, se lían enteramente a mano en Nicaragua; la casa no nombra la fábrica, ni la ciudad donde se encuentra.

En septiembre de 2026, el catálogo cuenta con tres líneas, según Cigarworld.de: Classic, calificada de más suave, con anilla azul; Torcidos, de doble capa, Connecticut claro y Maduro oscuro; Mezcla 40, bajo capa Connecticut de Ecuador, con notas dulces y especiadas. Una cuarta línea, Reserva de Oro, con anilla roja, ya no figura en él.',
        '[{"name":"Classic","color":"#8B5A2B","force":null,"wrapper":"No divulgada","vitolas":[],"story":"Con anilla azul, calificada de más suave por Cigarworld.de."},{"name":"Torcidos","color":"#6B4226","force":null,"wrapper":"Connecticut / Maduro","vitolas":[],"story":"Doble capa contrastada, Connecticut claro y Maduro oscuro, según cigarworld.de."},{"name":"Mezcla 40","color":"#C9A96E","force":null,"wrapper":"Connecticut ecuatoriano","vitolas":[],"story":"Notas dulces y especiadas bajo capa Connecticut ecuatoriana, según cigarworld.de."}]',
        'Chinchalero wird 2011 von John Atherton gegründet, der mehrere Jahre bei der internationalen Abteilung von General Cigar verbrachte, so Cigarworld.de. Der Name verweist auf die chinchales, die kleinen Werkstätten, in denen die Zigarre traditionell gedreht wird.

Die Zigarren, Longfiller, werden in Nicaragua vollständig von Hand gedreht; das Haus nennt weder die Fabrik noch die Stadt, in der sie sich befindet.

Im September 2026 umfasst das Sortiment drei Linien, so Cigarworld.de: Classic, als milder bezeichnet, mit blauer Bauchbinde; Torcidos, mit doppeltem Deckblatt, hellem Connecticut und dunklem Maduro; Mezcla 40, unter ecuadorianischem Connecticut-Deckblatt, mit süßen und würzigen Noten. Eine vierte Linie, Reserva de Oro, mit roter Bauchbinde, ist dort nicht mehr gelistet.',
        '[{"name":"Classic","color":"#8B5A2B","force":null,"wrapper":"Nicht angegeben","vitolas":[],"story":"Mit blauer Bauchbinde, von Cigarworld.de als milder bezeichnet."},{"name":"Torcidos","color":"#6B4226","force":null,"wrapper":"Connecticut / Maduro","vitolas":[],"story":"Kontrastierendes doppeltes Deckblatt, helles Connecticut und dunkles Maduro, so cigarworld.de."},{"name":"Mezcla 40","color":"#C9A96E","force":null,"wrapper":"Ecuadorianisches Connecticut","vitolas":[],"story":"Süße und würzige Noten unter ecuadorianischem Connecticut-Deckblatt, so cigarworld.de."}]',
        'Chinchalero由John Atherton于2011年创立，他曾在General Cigar的国际部门工作多年，据Cigarworld.de报道。品牌名称源自chinchales——传统上用来手工卷制雪茄的小作坊。

这些雪茄属于longfiller，在尼加拉瓜完全手工卷制；厂方未透露卷制工厂的名称，也未透露其所在城市。

截至2026年9月，据Cigarworld.de介绍，产品目录共有三条系列：Classic，被称为力度较柔和，配蓝色雪茄环；Torcidos，采用双层茄衣，浅色Connecticut与深色Maduro；Mezcla 40，茄衣为厄瓜多尔Connecticut，带甜味与辛香风味。第四条系列Reserva de Oro，配红色雪茄环，已不在目录之中。',
        '[{"name":"Classic","color":"#8B5A2B","force":null,"wrapper":"未公开","vitolas":[],"story":"配蓝色雪茄环，Cigarworld.de称其力度较柔和。"},{"name":"Torcidos","color":"#6B4226","force":null,"wrapper":"Connecticut / Maduro","vitolas":[],"story":"双层对比茄衣，浅色Connecticut搭配深色Maduro，据cigarworld.de介绍。"},{"name":"Mezcla 40","color":"#C9A96E","force":null,"wrapper":"厄瓜多尔Connecticut","vitolas":[],"story":"据cigarworld.de介绍，茄衣为厄瓜多尔Connecticut，带甜味与辛香风味。"}]',
        'تأسست Chinchalero عام 2011 على يد John Atherton، الذي أمضى عدة سنوات في القسم الدولي لشركة General Cigar، بحسب Cigarworld.de. يشير اسم العلامة إلى مصطلح chinchales، وهو تسمية للورش الصغيرة التي يُلفّ فيها السيجار تقليديًا.

تُلفّ هذه السجائر، وهي من نوع longfiller، يدويًا بالكامل في نيكاراغوا؛ ولا تكشف الدار عن اسم المصنع ولا عن المدينة التي يقع فيها.

حتى سبتمبر 2026، يضمّ الكتالوج ثلاثة خطوط، بحسب Cigarworld.de: Classic، الذي يوصف بأنه أخف قوةً، بحلقة زرقاء؛ وTorcidos، بغلاف مزدوج من Connecticut الفاتح وMaduro الداكن؛ وMezcla 40، بغلاف Connecticut إكوادوري، بنكهات حلوة وحارة. أما الخط الرابع، Reserva de Oro، بحلقة حمراء، فلم يعد مدرجًا فيه.',
        '[{"name":"Classic","color":"#8B5A2B","force":null,"wrapper":"غير معلن","vitolas":[],"story":"بحلقة زرقاء، تصفه Cigarworld.de بأنه أخف قوةً."},{"name":"Torcidos","color":"#6B4226","force":null,"wrapper":"Connecticut / Maduro","vitolas":[],"story":"غلاف مزدوج متباين الألوان، Connecticut فاتح وMaduro داكن، بحسب cigarworld.de."},{"name":"Mezcla 40","color":"#C9A96E","force":null,"wrapper":"Connecticut إكوادوري","vitolas":[],"story":"نكهات حلوة وحارة تحت غلاف Connecticut إكوادوري، بحسب cigarworld.de."}]')
