   'indonesia : Mata Hari, Atatürk, Chone'),
  (NULL,'migration 241','systeme','recensement_8_fiches','marque',0,
   'nicaragua : Cuervo y Sobrinos, Ann-Eks, BerlinCigarMen, Canned Heat, Casa Culinaria, Casagranda, Chinchalero, Perla de Calvano'),
