   'honduras : Barrio Viejo');

SELECT
  (SELECT COUNT(*) FROM `brands` WHERE `name` IN ('DBL','Mata Hari','Cuervo y Sobrinos','Ann-Eks','BerlinCigarMen','Canned Heat','Casa Culinaria','Casagranda','Barrio Viejo','Atatürk','Chone','Chinchalero','Perla de Calvano')) = 13 AS fiches,
  (SELECT JSON_CONTAINS(JSON_EXTRACT(`brands`, '$[*].name'), '"DBL"') FROM `producer_countries` WHERE `id` = 'dominican') AS dominican_annonce,
  (SELECT JSON_CONTAINS(JSON_EXTRACT(`brands`, '$[*].name'), '"Mata Hari"') AND JSON_CONTAINS(JSON_EXTRACT(`brands`, '$[*].name'), '"Atatürk"') AND JSON_CONTAINS(JSON_EXTRACT(`brands`, '$[*].name'), '"Chone"') FROM `producer_countries` WHERE `id` = 'indonesia') AS indonesia_annonce,
  (SELECT JSON_CONTAINS(JSON_EXTRACT(`brands`, '$[*].name'), '"Cuervo y Sobrinos"') AND JSON_CONTAINS(JSON_EXTRACT(`brands`, '$[*].name'), '"Ann-Eks"') AND JSON_CONTAINS(JSON_EXTRACT(`brands`, '$[*].name'), '"BerlinCigarMen"') AND JSON_CONTAINS(JSON_EXTRACT(`brands`, '$[*].name'), '"Canned Heat"') AND JSON_CONTAINS(JSON_EXTRACT(`brands`, '$[*].name'), '"Casa Culinaria"') AND JSON_CONTAINS(JSON_EXTRACT(`brands`, '$[*].name'), '"Casagranda"') AND JSON_CONTAINS(JSON_EXTRACT(`brands`, '$[*].name'), '"Chinchalero"') AND JSON_CONTAINS(JSON_EXTRACT(`brands`, '$[*].name'), '"Perla de Calvano"') FROM `producer_countries` WHERE `id` = 'nicaragua') AS nicaragua_annonce,
  (SELECT JSON_CONTAINS(JSON_EXTRACT(`brands`, '$[*].name'), '"Barrio Viejo"') FROM `producer_countries` WHERE `id` = 'honduras') AS honduras_annonce,
  (SELECT COUNT(*) FROM `translation_status` WHERE `entite` = 'brands' AND `entite_id` IN ('DBL','Mata Hari','Cuervo y Sobrinos','Ann-Eks','BerlinCigarMen','Canned Heat','Casa Culinaria','Casagranda','Barrio Viejo','Atatürk','Chone','Chinchalero','Perla de Calvano')) = 130 AS sceaux,
  (SELECT SUM(CHAR_LENGTH(`detail`) >= 255) = 0 FROM `moderation_log` WHERE `acteur_nom` = 'migration 241') AS journal_non_tronque;
SELECT COUNT(*) AS marques, SUM(TRIM(COALESCE(`source`,'')) = '') AS sans_source FROM `brands`;
